    (4348, N'Bid Ask Cumulative Delta from Market Data', N'BidAskCumulativeDeltaExample.cs', N'C#', N'Indicator', N'cumulative delta, bid ask delta, order flow, buying pressure, selling pressure, trade classification, OnMarketData, market data events, Tick Replay, session reset, uptick downtick', N'#region Using declarations
using System.ComponentModel.DataAnnotations;
using System.Windows.Media;
using NinjaTrader.Data;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class BidAskCumulativeDeltaExample : Indicator
    {
        private long cumulativeDelta;
        private double previousTradePrice;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Bid Ask Cumulative Delta Example";
                Description = "Accumulates trade volume classified at the bid or ask.";
                Calculate = Calculate.OnEachTick;
                IsOverlay = false;
                IsSuspendedWhileInactive = false;
                ResetEachSession = true;
                AddPlot(Brushes.DodgerBlue, "CumulativeDelta");
                AddLine(Brushes.Gray, 0, "Zero");
            }
        }

        protected override void OnBarUpdate()
        {
            if (ResetEachSession && Bars.IsFirstBarOfSession && IsFirstTickOfBar)
                cumulativeDelta = 0;

            Value[0] = cumulativeDelta;
        }

        protected override void OnMarketData(MarketDataEventArgs update)
        {
            if (update.MarketDataType != MarketDataType.Last || update.Volume <= 0)
                return;

            if (update.Ask > 0 && update.Price >= update.Ask)
                cumulativeDelta += update.Volume;
            else if (update.Bid > 0 && update.Price <= update.Bid)
                cumulativeDelta -= update.Volume;
            else if (previousTradePrice > 0)
                cumulativeDelta += update.Price >= previousTradePrice
                    ? update.Volume
                    : -update.Volume;

            previousTradePrice = update.Price;
        }

        [NinjaScriptProperty]
        [Display(Name = "Reset Each Session", GroupName = "Parameters", Order = 0)]
        public bool ResetEachSession { get; set; }
    }
