    INSERT INTO #NinjaTraderRagUpdate
    (Id, Title, FilePath, Language, Category, Tags, Content, Embedding, Description, RagLevel)
    VALUES
    (4352, N'Break-Even and Trailing Stop Management', N'TrailingStopBreakevenExample.cs', N'C#', N'Strategy', N'trailing stop strategy, break even stop, ChangeOrder, dynamic stop loss, OnExecutionUpdate, partial fills, average entry price, profit protection, GetCurrentBid', N'#region Using declarations
using System;
using System.ComponentModel.DataAnnotations;
using NinjaTrader.Cbi;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class TrailingStopBreakevenExample : Strategy
    {
        private Order entryOrder;
        private Order stopOrder;
        private double averageEntryPrice;
        private int filledQuantity;
        private double fillValue;
        private double activeStopPrice;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "TrailingStopBreakevenExample";
                Calculate = Calculate.OnPriceChange;
                InitialStopTicks = 12;
                BreakevenTriggerTicks = 8;
                BreakevenPlusTicks = 1;
                TrailTriggerTicks = 16;
                TrailDistanceTicks = 8;
            }
        }

        protected override void OnBarUpdate()
        {
            if (CurrentBar < 20)
                return;

            if (Position.MarketPosition == MarketPosition.Flat && entryOrder == null)
            {
                if (CrossAbove(Close, SMA(20), 1))
                    EnterLong(2, "Entry");
                return;
            }

            if (Position.MarketPosition != MarketPosition.Long ||
                stopOrder == null ||
                stopOrder.OrderState is not (OrderState.Accepted or OrderState.Working))
                return;

            double openProfitTicks = (Close[0] - averageEntryPrice) / TickSize;
            double desiredStop = activeStopPrice;

            if (openProfitTicks >= BreakevenTriggerTicks)
                desiredStop = Math.Max(desiredStop, averageEntryPrice + BreakevenPlusTicks * TickSize);

            if (openProfitTicks >= TrailTriggerTicks)
                desiredStop = Math.Max(desiredStop, Close[0] - TrailDistanceTicks * TickSize);

            desiredStop = Instrument.MasterInstrument.RoundToTickSize(desiredStop);
            if (desiredStop > activeStopPrice && desiredStop < GetCurrentBid())
            {
                activeStopPrice = desiredStop;
                ChangeOrder(stopOrder, filledQuantity, 0, activeStopPrice);
            }
        }

        protected override void OnOrderUpdate(
            Order order,
            double limitPrice,
            double stopPrice,
            int quantity,
            int filled,
            double averageFillPrice,
            OrderState orderState,
            DateTime time,
            ErrorCode error,
            string nativeError)
        {
            if (order.Name == "Entry")
                entryOrder = order;
            else if (order.Name == "DynamicStop")
                stopOrder = order;

            if (order == entryOrder &&
                orderState is OrderState.Cancelled or OrderState.Rejected)
                entryOrder = null;

            if (order == stopOrder &&
                orderState is OrderState.Filled or OrderState.Cancelled or OrderState.Rejected)
                stopOrder = null;
        }

        protected override void OnExecutionUpdate(
            Execution execution,
            string executionId,
            double price,
            int quantity,
            MarketPosition marketPosition,
            string orderId,
            DateTime time)
        {
            if (entryOrder == null || execution.Order != entryOrder)
                return;

            fillValue += price * quantity;
            filledQuantity += quantity;
            averageEntryPrice = fillValue / filledQuantity;
            activeStopPrice = Instrument.MasterInstrument.RoundToTickSize(
                averageEntryPrice - InitialStopTicks * TickSize);

            stopOrder = ExitLongStopMarket(
                0,
                true,
                filledQuantity,
                activeStopPrice,
                "DynamicStop",
                "Entry");

            if (execution.Order.OrderState == OrderState.Filled)
                entryOrder = null;
        }

        [Range(1, int.MaxValue), NinjaScriptProperty]
        [Display(Name = "Initial stop (ticks)", GroupName = "Risk", Order = 0)]
        public int InitialStopTicks { get; set; }

        [Range(1, int.MaxValue), NinjaScriptProperty]
        [Display(Name = "Breakeven trigger (ticks)", GroupName = "Risk", Order = 1)]
        public int BreakevenTriggerTicks { get; set; }

        [Range(0, int.MaxValue), NinjaScriptProperty]
        [Display(Name = "Breakeven plus (ticks)", GroupName = "Risk", Order = 2)]
        public int BreakevenPlusTicks { get; set; }

        [Range(1, int.MaxValue), NinjaScriptProperty]
        [Display(Name = "Trail trigger (ticks)", GroupName = "Risk", Order = 3)]
        public int TrailTriggerTicks { get; set; }

        [Range(1, int.MaxValue), NinjaScriptProperty]
        [Display(Name = "Trail distance (ticks)", GroupName = "Risk", Order = 4)]
        public int TrailDistanceTicks { get; set; }
