035827637,-0.04373169,-0.0034389496,-0.0010738373,-0.00076055527,-0.04458618,-0.024230957,0.020492554,0.0019779205,0.008255005,-0.009407043,-0.0044784546,-0.0016107559,0.03277588,0.020706177,0.004180908,0.017211914,0.022323608,0.022491455,0.000497818,0.0016899109,-0.010719299,-0.031463623,0.022445679,0.0005469322,-0.0023403168,-0.027435303,0.015655518,-0.008056641,0.0011196136,0.00012516975,0.015335083,-0.0037822723,0.015975952,-0.039367676,-0.031097412,-0.009559631,0.0005736351,-0.012939453,0.012565613,0.0031871796,0.030883789,0.00680542,0.0231781,0.031921387,0.0037841797,0.020935059,0.008911133,-0.011276245,-0.013694763,-0.014381409,-0.009765625,-0.041015625,-0.0035076141,-0.0035915375,-0.026000977,0.028686523,-0.0087890625,0.019088745,0.015655518,0.035003662,0.005821228,0.022827148,0.025817871,0.010246277,0.053375244,-0.020309448,0.040161133,0.0046310425,0.0073890686,0.051208496,-0.025238037,0.024993896,0.027709961,0.028335571,-0.01676941,0.014694214,-0.026473999,-0.0018835068,0.005531311,-0.0067367554,0.007457733,-0.018493652,0.008735657,-0.008514404,-0.017623901,0.013145447,0.0149383545,0.008598328,0.060272217,-0.01309967,0.03253174,0.023025513,-0.00491333,-0.009757996,-0.031021118,-0.0034618378,-0.0050354004]', N'Creates a fill-aware protective stop, moves it to break even after a profit threshold and then trails price. Handles partial entry fills, tick-size rounding and validates stop changes against the current bid.', N'Minimal'),
    (4353, N'Buy and Sell Volume at Price Dictionary', N'BuySellVolumeOneTickAtPriceDictionaryExample.cs', N'C#', N'Indicator', N'NinjaScript, Indicator, Buy Volume, Sell Volume, Volume at Price, Dictionary, Tick Data, Bid Ask, Order Flow, Tick Replay, Multi-Series', N'#region Using declarations
using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Linq;
using System.Windows.Media;
using System.Xml.Serialization;
using NinjaTrader.Data;
using NinjaTrader.Gui.Chart;
using NinjaTrader.Gui.Tools;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Indicators.DataManagementExamples
{
	public class BuySellVolumeOneTickAtPriceDictionaryExample : Indicator
	{
		private double buys;
		private double sells;
		private bool lastInTransition;
		private int lastBar;

		private Series<Dictionary<double, long>> askVolumeByPrice;
		private Series<Dictionary<double, long>> bidVolumeByPrice;

		private Dictionary<double, long> temporaryAskVolume;
		private Dictionary<double, long> temporaryBidVolume;

		protected override void OnStateChange()
		{
			if (State == State.SetDefaults)
			{
				Description = @"Demonstrates calculating buy and sell volume from one-tick data and storing volume at each price in dictionaries.";
				Name = "BuySellVolumeOneTickAtPriceDictionaryExample";

				AddPlot(
					new Stroke(Brushes.DarkCyan, 2),
					PlotStyle.Bar,
					"BuyVolume");

				AddPlot(
					new Stroke(Brushes.Crimson, 2),
					PlotStyle.Bar,
					"SellVolume");

				AddPlot(
					new Stroke(Brushes.DarkCyan, 2),
					PlotStyle.Bar,
					"BuyVolumeFromDictionary");

				AddPlot(
					new Stroke(Brushes.Crimson, 2),
					PlotStyle.Bar,
					"SellVolumeFromDictionary");
			}
			else if (State == State.Configure)
			{
				AddDataSeries(BarsPeriodType.Tick, 1);
			}
			else if (State == State.DataLoaded)
			{
				askVolumeByPrice =
					new Series<Dictionary<double, long>>(
						this,
						MaximumBarsLookBack.Infinite);

				bidVolumeByPrice =
					new Series<Dictionary<double, long>>(
						this,
						MaximumBarsLookBack.Infinite);

				temporaryAskVolume = new Dictionary<double, long>();
				temporaryBidVolume = new Dictionary<double, long>();
			}
		}

		protected override void OnBarUpdate()
		{
			if (CurrentBars[0] < 0 || CurrentBars[1] < 0)
				return;

			if (BarsInProgress == 0)
			{
				int indexOffset =
					BarsArray[1].Count - 1 - CurrentBars[1];

				if (IsFirstTickOfBar
					&& Calculate != Calculate.OnBarClose
					&& (State == State.Realtime
						|| BarsArray[0].IsTickReplay))
				{
					// Update the completed primary bar with its final tick.
					if (CurrentBars[0] > 0)
						SetValues(1);

					if (BarsArray[0].IsTickReplay
						|| (State == State.Realtime
							&& indexOffset == 0))
					{
						ResetValues(false, false);
					}
				}

				// Values are assigned only from the primary series.
				SetValues(0);

				if (Calculate == Calculate.OnBarClose
					|| (lastBar != CurrentBars[0]
						&& ((State == State.Historical
								&& indexOffset > 1)
							|| (State == State.Realtime
								&& indexOffset == 0))))
				{
					ResetValues(false, false);
				}
				else if (Calculate != Calculate.OnBarClose
					&& State == State.Historical
					&& indexOffset == 1)
				{
					ResetValues(false, true);
				}

				lastBar = CurrentBars[0];
			}
			else if (BarsInProgress == 1)
			{
				if (BarsArray[1].IsFirstBarOfSession)
					ResetValues(true, false);

				CalculateValues(false);
			}
		}

		private void CalculateValues(bool forceCurrentBar)
		{
			int indexOffset =
				BarsArray[1].Count - 1 - CurrentBars[1];

			bool inTransition =
				State == State.Realtime && indexOffset > 1;

			if (!inTransition
				&& lastInTransition
				&& !forceCurrentBar
				&& Calculate == Calculate.OnBarClose)
			{
				CalculateValues(true);
			}

			bool useCurrentBar =
				State == State.Historical
				|| inTransition
				|| Calculate != Calculate.OnBarClose
				|| forceCurrentBar;

			int tickBarIndex = useCurrentBar
				? CurrentBars[1]
				: Math.Min(
					CurrentBars[1] + 1,
					BarsArray[1].Count - 1);

			long volume = BarsArray[1].GetVolume(tickBarIndex);
			double price = BarsArray[1].GetClose(tickBarIndex);
			double ask = BarsArray[1].GetAsk(tickBarIndex);
			double bid = BarsArray[1].GetBid(tickBarIndex);

			if (price >= ask)
			{
				buys += volume;
				AddVolume(temporaryAskVolume, price, volume);
			}
			else if (price <= bid)
			{
				sells += volume;
				AddVolume(temporaryBidVolume, price, volume);
			}

			lastInTransition = inTransition;
		}

		private void AddVolume(
			Dictionary<double, long> volumeDictionary,
			double price,
			long volume)
		{
			if (volumeDictionary.ContainsKey(price))
				volumeDictionary[price] += volume;
			else
				volumeDictionary.Add(price, volume);
		}

		private void SetValues(int barsAgo)
		{
			// BuyVolume follows the standard stacked BuySellVolume format:
			// total classified volume on top and sell volume below.
			BuyVolume[barsAgo] = buys + sells;
			SellVolume[barsAgo] = sells;

			askVolumeByPrice[barsAgo] =
				new Dictionary<double, long>(temporaryAskVolume);

			bidVolumeByPrice[barsAgo] =
				new Dictionary<double, long>(temporaryBidVolume);

			long askTotalVolume = 0;

			foreach (KeyValuePair<double, long> entry
				in askVolumeByPrice[barsAgo])
			{
				Print(string.Format(
					"{0} | Ask | {1}: {2}",
					Time[barsAgo],
					entry.Key,
					entry.Value));

				askTotalVolume += entry.Value;
			}

			BuyVolumeDictionary[barsAgo] = askTotalVolume;

			long bidTotalVolume = 0;

			foreach (KeyValuePair<double, long> entry
				in bidVolumeByPrice[barsAgo])
			{
				Print(string.Format(
					"{0} | Bid | {1}: {2}",
					Time[barsAgo],
					entry.Key,
					entry.Value));

				bidTotalVolume += entry.Value;
			}

			SellVolumeDictionary[barsAgo] = bidTotalVolume;

			// Use the same stacked-plot format as the standard plots.
			BuyVolumeDictionary[barsAgo] +=
				SellVolumeDictionary[barsAgo];
		}

		private void ResetValues(
			bool isNewSession,
			bool isTransition)
		{
			if (isTransition)
			{
				// Remove values already assigned to the transition bar.
				buys -= BuyVolume[0] - SellVolume[0];
				sells -= SellVolume[0];

				SubtractBarVolume(
					temporaryAskVolume,
					askVolumeByPrice[0]);

				SubtractBarVolume(
					temporaryBidVolume,
					bidVolumeByPrice[0]);
			}
			else
			{
				buys = 0;
				sells = 0;

				temporaryAskVolume.Clear();
				temporaryBidVolume.Clear();
			}

			if (isNewSession)
			{
				// Add session-cumulative reset logic here if required.
			}
		}

		private void SubtractBarVolume(
			Dictionary<double, long> temporaryVolume,
			Dictionary<double, long> completedBarVolume)
		{
			if (completedBarVolume == null)
				return;

			foreach (double price in temporaryVolume.Keys.ToList())
			{
				long barVolume;

				if (!completedBarVolume.TryGetValue(
					price,
					out barVolume))
				{
					continue;
				}

				temporaryVolume[price] -= barVolume;

				if (temporaryVolume[price] <= 0)
					temporaryVolume.Remove(price);
			}
		}

		[Browsable(false)]
		[XmlIgnore]
		public Series<double> BuyVolume
		{
			get { return Values[0]; }
		}

		[Browsable(false)]
		[XmlIgnore]
		public Series<double> SellVolume
		{
			get { return Values[1]; }
		}

		[Browsable(false)]
		[XmlIgnore]
		public Series<double> BuyVolumeDictionary
		{
			get { return Values[2]; }
		}

		[Browsable(false)]
		[XmlIgnore]
		public Series<double> SellVolumeDictionary
		{
			get { return Values[3]; }
