    (4356, N'Choppiness Index for Trending and Ranging Markets', N'ChoppinessIndex.cs', N'C#', N'Indicator', N'Choppiness Index, choppy market, ranging market, trending market, trend strength, consolidation, sideways market, ATR range ratio, logarithmic oscillator, 38.2 level, 62.8 level, market regime', N'
#region Using declarations
using System;
using System.ComponentModel.DataAnnotations;
using System.Windows.Media;
using NinjaTrader.Core.FloatingPoint;
#endregion

// This namespace holds indicators in this folder and is required. Do not change it.
namespace NinjaTrader.NinjaScript.Indicators
{
	public class ChoppinessIndex : Indicator
	{
		protected override void OnStateChange()
		{
			if (State == State.SetDefaults)
			{
				Description = Custom.Resource.NinjaScriptIndicatorDescriptionChoppinessIndex;
				Name		= Custom.Resource.NinjaScriptIndicatorNameChoppinessIndex;
				IsOverlay	= false;
				Period		= 14;

				AddPlot(Brushes.DodgerBlue,		Custom.Resource.NinjaScriptIndicatorNameChoppinessIndex);
				AddLine(Brushes.DarkCyan, 38.2,	Custom.Resource.NinjaScriptIndicatorStrong);
				AddLine(Brushes.DarkCyan, 62.8,	Custom.Resource.NinjaScriptIndicatorChoppy);
			}
		}

		protected override void OnBarUpdate() => Value[0] = (MAX(High, Period)[0] - MIN(Low, Period)[0]).ApproxCompare(0) == 0 || SUM(ATR(1), Period)[0].ApproxCompare(0) == 0 ? 0 : 100 * Math.Log10(SUM(ATR(1), Period)[0] / (MAX(High, Period)[0] - MIN(Low, Period)[0])) / Math.Log10(Period);

		#region Properties
		[Range(2, int.MaxValue), NinjaScriptProperty]
		[Display(ResourceType = typeof(Custom.Resource), Name = "Period", GroupName = "NinjaScriptParameters", Order = 0)]
		public int Period { get; set; }
		#endregion
	}
}
