    (4374, N'Level II Market Depth Imbalance', N'MarketDepthImbalanceExample.cs', N'C#', N'Indicator', N'market depth, Level II, order book imbalance, DOM imbalance, bid liquidity, ask liquidity, depth levels, OnMarketDepth, MarketDepthEventArgs, add update remove, thread safety, real-time liquidity', N'#region Using declarations
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using System.Windows.Media;
using NinjaTrader.Data;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class MarketDepthImbalanceExample : Indicator
    {
        private readonly object depthLock = new object();
        private readonly Dictionary<int, long> bids = new Dictionary<int, long>();
        private readonly Dictionary<int, long> asks = new Dictionary<int, long>();

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Market Depth Imbalance Example";
                Description = "Measures bid and ask liquidity imbalance from Level II updates.";
                Calculate = Calculate.OnEachTick;
                IsOverlay = false;
                IsSuspendedWhileInactive = false;
                DepthLevels = 5;
                AddPlot(Brushes.DodgerBlue, "ImbalancePercent");
                AddLine(Brushes.Gray, 0, "Balanced");
            }
            else if (State == State.Terminated)
            {
                lock (depthLock)
                {
                    bids.Clear();
                    asks.Clear();
                }
            }
        }

        protected override void OnMarketDepth(MarketDepthEventArgs update)
        {
            Dictionary<int, long> side = update.MarketDataType == MarketDataType.Bid
                ? bids
                : update.MarketDataType == MarketDataType.Ask ? asks : null;

            if (side == null)
                return;

            lock (depthLock)
                ApplyDepthUpdate(side, update);
        }

        private void ApplyDepthUpdate(
            Dictionary<int, long> side,
            MarketDepthEventArgs update)
        {
            if (update.Operation == Operation.Update)
            {
                side[update.Position] = update.Volume;
                return;
            }

            Dictionary<int, long> shifted = new Dictionary<int, long>();

            foreach (KeyValuePair<int, long> level in side)
            {
                if (update.Operation == Operation.Add)
                {
                    int newPosition = level.Key >= update.Position
                        ? level.Key + 1
                        : level.Key;
                    shifted[newPosition] = level.Value;
                }
                else if (update.Operation == Operation.Remove
                    && level.Key != update.Position)
                {
                    int newPosition = level.Key > update.Position
                        ? level.Key - 1
                        : level.Key;
                    shifted[newPosition] = level.Value;
                }
            }

            side.Clear();
            foreach (KeyValuePair<int, long> level in shifted)
                side[level.Key] = level.Value;

            if (update.Operation == Operation.Add)
                side[update.Position] = update.Volume;
        }

        protected override void OnBarUpdate()
        {
            long bidVolume = 0;
            long askVolume = 0;

            lock (depthLock)
            {
                for (int level = 0; level < DepthLevels; level++)
                {
                    long volume;
                    if (bids.TryGetValue(level, out volume))
                        bidVolume += volume;
                    if (asks.TryGetValue(level, out volume))
                        askVolume += volume;
                }
            }

            long total = bidVolume + askVolume;
            Value[0] = total == 0 ? 0 : 100.0 * (bidVolume - askVolume) / total;
        }

        [Range(1, 20)]
        [NinjaScriptProperty]
        [Display(Name = "Depth Levels", GroupName = "Parameters", Order = 0)]
        public int DepthLevels { get; set; }
