    INSERT INTO #NinjaTraderRagUpdate
    (Id, Title, FilePath, Language, Category, Tags, Content, Embedding, Description, RagLevel)
    VALUES
    (4377, N'Managed Strategy with Stop Loss and Profit Target', N'ManagedStopsTargetsExample.cs', N'C#', N'Strategy', N'managed strategy, stop loss, profit target, EnterLong, EnterShort, SetStopLoss, SetProfitTarget, BarsSinceEntryExecution, time exit, risk management', N'#region Using declarations
using System;
using System.ComponentModel.DataAnnotations;
using NinjaTrader.Cbi;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class ManagedStopsTargetsExample : Strategy
    {
        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "ManagedStopsTargetsExample";
                Calculate = Calculate.OnBarClose;
                EntriesPerDirection = 1;
                EntryHandling = EntryHandling.AllEntries;
                StopLossTicks = 12;
                ProfitTargetTicks = 24;
                MaximumBarsInTrade = 20;
            }
            else if (State == State.Configure)
            {
                SetStopLoss("LongEntry", CalculationMode.Ticks, StopLossTicks, false);
                SetProfitTarget("LongEntry", CalculationMode.Ticks, ProfitTargetTicks);
                SetStopLoss("ShortEntry", CalculationMode.Ticks, StopLossTicks, false);
                SetProfitTarget("ShortEntry", CalculationMode.Ticks, ProfitTargetTicks);
            }
        }

        protected override void OnBarUpdate()
        {
            if (CurrentBar < 20)
                return;

            if (Position.MarketPosition == MarketPosition.Flat)
            {
                if (CrossAbove(Close, SMA(20), 1))
                    EnterLong(1, "LongEntry");
                else if (CrossBelow(Close, SMA(20), 1))
                    EnterShort(1, "ShortEntry");

                return;
            }

            int barsInTrade = BarsSinceEntryExecution();
            if (barsInTrade < MaximumBarsInTrade)
                return;

            if (Position.MarketPosition == MarketPosition.Long)
                ExitLong("TimeExit", "LongEntry");
            else if (Position.MarketPosition == MarketPosition.Short)
                ExitShort("TimeExit", "ShortEntry");
        }

        [Range(1, int.MaxValue), NinjaScriptProperty]
        [Display(Name = "Stop loss (ticks)", GroupName = "Risk", Order = 0)]
        public int StopLossTicks { get; set; }

        [Range(1, int.MaxValue), NinjaScriptProperty]
        [Display(Name = "Profit target (ticks)", GroupName = "Risk", Order = 1)]
        public int ProfitTargetTicks { get; set; }

        [Range(1, int.MaxValue), NinjaScriptProperty]
        [Display(Name = "Maximum bars in trade", GroupName = "Risk", Order = 2)]
        public int MaximumBarsInTrade { get; set; }
    }
