    (4384, N'Multi-Timeframe Strategy with Higher-Timeframe Filter', N'MultiTimeframeStrategyExample.cs', N'C#', N'Strategy', N'multi-timeframe strategy, AddDataSeries, BarsInProgress, CurrentBars, Closes, BarsArray, higher timeframe filter, secondary series, SMA filter', N'#region Using declarations
using System;
using System.ComponentModel.DataAnnotations;
using NinjaTrader.Cbi;
using NinjaTrader.Data;
using NinjaTrader.NinjaScript.Indicators;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class MultiTimeframeStrategyExample : Strategy
    {
        private SMA higherTimeframeSma;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "MultiTimeframeStrategyExample";
                Calculate = Calculate.OnBarClose;
                HigherTimeframeMinutes = 15;
                HigherTimeframePeriod = 20;
            }
            else if (State == State.Configure)
            {
                AddDataSeries(BarsPeriodType.Minute, HigherTimeframeMinutes);
            }
            else if (State == State.DataLoaded)
            {
                higherTimeframeSma = SMA(BarsArray[1], HigherTimeframePeriod);
            }
        }

        protected override void OnBarUpdate()
        {
            if (BarsInProgress != 0)
                return;

            if (CurrentBars[0] < 2 || CurrentBars[1] < HigherTimeframePeriod)
                return;

            bool higherTimeframeBullish = Closes[1][0] > higherTimeframeSma[0];
            bool primarySignal = Close[0] > High[1];

            if (Position.MarketPosition == MarketPosition.Flat &&
                higherTimeframeBullish &&
                primarySignal)
                EnterLong("HigherTimeframeLong");

            if (Position.MarketPosition == MarketPosition.Long &&
                Closes[1][0] < higherTimeframeSma[0])
                ExitLong("HigherTimeframeExit", "HigherTimeframeLong");
        }

        [Range(1, 1440), NinjaScriptProperty]
        [Display(Name = "Higher timeframe (minutes)", GroupName = "Parameters", Order = 0)]
        public int HigherTimeframeMinutes { get; set; }

        [Range(1, int.MaxValue), NinjaScriptProperty]
        [Display(Name = "Higher timeframe SMA period", GroupName = "Parameters", Order = 1)]
        public int HigherTimeframePeriod { get; set; }
    }
