    (4391, N'Partial Fill and Protective Order Handling', N'OrderExecutionHandlingExample.cs', N'C#', N'Strategy', N'OnOrderUpdate, OnExecutionUpdate, partial fills, rejected order, protective stop, profit target, OrderState, Execution, average fill price, order handling', N'#region Using declarations
using System;
using System.ComponentModel.DataAnnotations;
using System.Windows.Media;
using NinjaTrader.Cbi;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class OrderExecutionHandlingExample : Strategy
    {
        private Order entryOrder;
        private Order stopOrder;
        private Order targetOrder;
        private int entryFilled;
        private double entryFillValue;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "OrderExecutionHandlingExample";
                Calculate = Calculate.OnBarClose;
                StopLossTicks = 12;
                ProfitTargetTicks = 24;
            }
        }

        protected override void OnBarUpdate()
        {
            if (CurrentBar < 20 || Position.MarketPosition != MarketPosition.Flat || entryOrder != null)
                return;

            if (CrossAbove(Close, SMA(20), 1))
                EnterLong(2, "Entry");
        }

        protected override void OnOrderUpdate(
            Order order,
            double limitPrice,
            double stopPrice,
            int quantity,
            int filled,
            double averageFillPrice,
            OrderState orderState,
            DateTime time,
            ErrorCode error,
            string nativeError)
        {
            if (order.Name == "Entry")
                entryOrder = order;
            else if (order.Name == "ProtectiveStop")
                stopOrder = order;
            else if (order.Name == "ProfitTarget")
                targetOrder = order;

            if (orderState == OrderState.Rejected)
            {
                Print($"Order rejected: {order.Name}; error={error}; message={nativeError}");

                if (order == entryOrder)
                    entryOrder = null;
            }

            if (order == entryOrder &&
                (orderState == OrderState.Cancelled || orderState == OrderState.Filled) &&
                order.Filled == 0)
                entryOrder = null;
        }

        protected override void OnExecutionUpdate(
            Execution execution,
            string executionId,
            double price,
            int quantity,
            MarketPosition marketPosition,
            string orderId,
            DateTime time)
        {
            if (entryOrder == null || execution.Order != entryOrder)
                return;

            entryFillValue += price * quantity;
            entryFilled += quantity;
            double averageEntry = entryFillValue / entryFilled;

            stopOrder = ExitLongStopMarket(
                0,
                true,
                entryFilled,
                averageEntry - StopLossTicks * TickSize,
                "ProtectiveStop",
                "Entry");

            targetOrder = ExitLongLimit(
                0,
                true,
                entryFilled,
                averageEntry + ProfitTargetTicks * TickSize,
                "ProfitTarget",
                "Entry");

            if (execution.Order.OrderState == OrderState.Filled)
                entryOrder = null;
        }

        [Range(1, int.MaxValue), NinjaScriptProperty]
        [Display(Name = "Stop loss (ticks)", GroupName = "Risk", Order = 0)]
        public int StopLossTicks { get; set; }

        [Range(1, int.MaxValue), NinjaScriptProperty]
        [Display(Name = "Profit target (ticks)", GroupName = "Risk", Order = 1)]
        public int ProfitTargetTicks { get; set; }
    }
