    INSERT INTO #NinjaTraderRagUpdate
    (Id, Title, FilePath, Language, Category, Tags, Content, Embedding, Description, RagLevel)
    VALUES
    (4397, N'Real-Time EMA Crossover Alerts', N'MovingAverageCrossAlertExample.cs', N'C#', N'Indicator', N'indicator alert, EMA crossover, moving average crossover, bullish cross, bearish cross, CrossAbove, CrossBelow, Alert method, real-time alert, sound alert, rearm interval, historical alert prevention', N'#region Using declarations
using System.ComponentModel.DataAnnotations;
using System.Windows.Media;
using NinjaTrader.Cbi;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class MovingAverageCrossAlertExample : Indicator
    {
        private EMA fastEma;
        private EMA slowEma;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Moving Average Cross Alert Example";
                Description = "Raises real-time alerts when fast and slow moving averages cross.";
                Calculate = Calculate.OnBarClose;
                IsOverlay = true;
                IsSuspendedWhileInactive = true;
                FastPeriod = 9;
                SlowPeriod = 21;
                RearmSeconds = 30;
                AddPlot(Brushes.DodgerBlue, "FastEMA");
                AddPlot(Brushes.Goldenrod, "SlowEMA");
            }
            else if (State == State.DataLoaded)
            {
                fastEma = EMA(FastPeriod);
                slowEma = EMA(SlowPeriod);
            }
        }

        protected override void OnBarUpdate()
        {
            FastEMA[0] = fastEma[0];
            SlowEMA[0] = slowEma[0];

            if (State != State.Realtime || CurrentBar < SlowPeriod)
                return;

            if (CrossAbove(fastEma, slowEma, 1))
            {
                Alert("BullishEmaCross", Priority.Medium,
                    "Fast EMA crossed above slow EMA.",
                    NinjaTrader.Core.Globals.InstallDir + @"\sounds\Alert1.wav",
                    RearmSeconds, Brushes.Black, Brushes.LightGreen);
            }
            else if (CrossBelow(fastEma, slowEma, 1))
            {
                Alert("BearishEmaCross", Priority.Medium,
                    "Fast EMA crossed below slow EMA.",
                    NinjaTrader.Core.Globals.InstallDir + @"\sounds\Alert1.wav",
                    RearmSeconds, Brushes.White, Brushes.Crimson);
            }
        }

        [Range(1, 200)]
        [NinjaScriptProperty]
        [Display(Name = "Fast Period", GroupName = "Parameters", Order = 0)]
        public int FastPeriod { get; set; }

        [Range(2, 500)]
        [NinjaScriptProperty]
        [Display(Name = "Slow Period", GroupName = "Parameters", Order = 1)]
        public int SlowPeriod { get; set; }

        [Range(0, 3600)]
        [NinjaScriptProperty]
        [Display(Name = "Rearm Seconds", GroupName = "Parameters", Order = 2)]
        public int RearmSeconds { get; set; }

        public Series<double> FastEMA => Values[0];
        public Series<double> SlowEMA => Values[1];
    }
