    (4400, N'Session Opening Range High and Low', N'SessionOpeningRangeExample.cs', N'C#', N'Indicator', N'opening range indicator, initial balance, session high low, opening range breakout, ORB, first minutes of session, SessionIterator, session reset, intraday levels, support resistance', N'#region Using declarations
using System;
using System.ComponentModel.DataAnnotations;
using System.Windows.Media;
using NinjaTrader.Data;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SessionOpeningRangeExample : Indicator
    {
        private SessionIterator sessionIterator;
        private DateTime rangeEnd;
        private double rangeHigh;
        private double rangeLow;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Session Opening Range Example";
                Description = "Plots the high and low formed during the first minutes of each session.";
                Calculate = Calculate.OnBarClose;
                IsOverlay = true;
                IsSuspendedWhileInactive = true;
                OpeningRangeMinutes = 30;
                AddPlot(Brushes.SeaGreen, "OpeningRangeHigh");
                AddPlot(Brushes.Crimson, "OpeningRangeLow");
            }
            else if (State == State.DataLoaded)
                sessionIterator = new SessionIterator(Bars);
        }

        protected override void OnBarUpdate()
        {
            if (!Bars.BarsType.IsIntraday)
                return;

            if (Bars.IsFirstBarOfSession)
            {
                sessionIterator.GetNextSession(Time[0], true);
                rangeEnd = sessionIterator.ActualSessionBegin.AddMinutes(OpeningRangeMinutes);
                rangeHigh = High[0];
                rangeLow = Low[0];
            }

            if (Time[0] < rangeEnd)
            {
                rangeHigh = Math.Max(rangeHigh, High[0]);
                rangeLow = Math.Min(rangeLow, Low[0]);
            }

            OpeningRangeHigh[0] = rangeHigh;
            OpeningRangeLow[0] = rangeLow;
        }

        [Range(1, 240)]
        [NinjaScriptProperty]
        [Display(Name = "Opening Range Minutes", GroupName = "Parameters", Order = 0)]
        public int OpeningRangeMinutes { get; set; }

        public Series<double> OpeningRangeHigh => Values[0];
        public Series<double> OpeningRangeLow => Values[1];
    }
