    (4401, N'Session VWAP with Standard Deviation Bands', N'SessionVwapBandsExample.cs', N'C#', N'Indicator', N'session VWAP, volume weighted average price, VWAP bands, standard deviation bands, session reset, cumulative volume, typical price, institutional benchmark, volatility bands', N'#region Using declarations
using System;
using System.ComponentModel.DataAnnotations;
using System.Windows.Media;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SessionVwapBandsExample : Indicator
    {
        private double cumulativeVolume;
        private double cumulativePriceVolume;
        private double cumulativePriceSquaredVolume;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Session VWAP Bands Example";
                Description = "Calculates session VWAP and volume-weighted deviation bands.";
                Calculate = Calculate.OnBarClose;
                IsOverlay = true;
                IsSuspendedWhileInactive = true;
                DeviationMultiplier = 1.0;

                AddPlot(Brushes.Goldenrod, "VWAP");
                AddPlot(Brushes.DodgerBlue, "UpperBand");
                AddPlot(Brushes.DodgerBlue, "LowerBand");
            }
        }

        protected override void OnBarUpdate()
        {
            if (Bars.IsFirstBarOfSession)
            {
                cumulativeVolume = 0;
                cumulativePriceVolume = 0;
                cumulativePriceSquaredVolume = 0;
            }

            double price = Typical[0];
            double volume = Volume[0];

            cumulativeVolume += volume;
            cumulativePriceVolume += price * volume;
            cumulativePriceSquaredVolume += price * price * volume;

            if (cumulativeVolume <= 0)
                return;

            double vwap = cumulativePriceVolume / cumulativeVolume;
            double variance = Math.Max(0,
                cumulativePriceSquaredVolume / cumulativeVolume - vwap * vwap);
            double deviation = Math.Sqrt(variance) * DeviationMultiplier;

            VWAP[0] = vwap;
            UpperBand[0] = vwap + deviation;
            LowerBand[0] = vwap - deviation;
        }

        [Range(0.1, 10)]
        [NinjaScriptProperty]
        [Display(Name = "Deviation Multiplier", GroupName = "Parameters", Order = 0)]
        public double DeviationMultiplier { get; set; }

        public Series<double> VWAP => Values[0];
        public Series<double> UpperBand => Values[1];
        public Series<double> LowerBand => Values[2];
    }
