    (4419, N'Weighted Moving Average WMA Indicator', N'WMA.cs', N'C#', N'Indicator', N'WMA indicator, Weighted Moving Average, weighted MA, recent price weighting, trend indicator, moving average crossover, dynamic support resistance, price smoothing, rolling calculation', N'
#region Using declarations
using System;
using System.ComponentModel.DataAnnotations;
using System.Windows.Media;
#endregion

// This namespace holds indicators in this folder and is required. Do not change it.
namespace NinjaTrader.NinjaScript.Indicators
{
	/// <summary>
	/// The WMA (Weighted Moving Average) is a Moving Average indicator that shows the average
	/// value of a security''s price over a period of time with special emphasis on the more recent
	/// portions of the time period under analysis as opposed to the earlier.
	/// </summary>
	public class WMA : Indicator
	{
		private	int		myPeriod;
		private double	priorSum;
		private double	priorWsum;
		private double	sum;
		private double	wsum;

		protected override void OnStateChange()
		{
			if (State == State.SetDefaults)
			{

				Description					= Custom.Resource.NinjaScriptIndicatorDescriptionWMA;
				Name						= Custom.Resource.NinjaScriptIndicatorNameWMA;
				IsOverlay					= true;
				IsSuspendedWhileInactive	= true;
				Period						= 14;

				AddPlot(Brushes.Goldenrod, Custom.Resource.NinjaScriptIndicatorNameWMA);
			}
			else if (State == State.Configure)
			{
				priorSum	= 0;
				priorWsum	= 0;
				sum			= 0;
				wsum		= 0;
			}
		}

		protected override void OnBarUpdate()
		{
			if (BarsArray[0].BarsType.IsRemoveLastBarSupported)
			{
				if (CurrentBar == 0)
					Value[0] = Input[0];
				else
				{
					int		back	= Math.Min(Period - 1, CurrentBar);
					double	val		= 0;
					int		weight	= 0;
					for (int idx = back; idx >= 0; idx--)
					{
						val		+= (idx + 1) * Input[back - idx];
						weight	+= idx + 1;
					}
					Value[0] = val / weight;
				}
			}
			else
			{
				if (IsFirstTickOfBar)
				{
					priorWsum	= wsum;
					priorSum	= sum;
					myPeriod	= Math.Min(CurrentBar + 1, Period);
				}

				wsum		= priorWsum - (CurrentBar >= Period ? priorSum : 0) + myPeriod * Input[0];
				sum			= priorSum + Input[0] - (CurrentBar >= Period ? Input[Period] : 0);
				Value[0]	= wsum / (0.5 * myPeriod * (myPeriod + 1));
			}
		}

		#region Properties
		[Range(1, int.MaxValue), NinjaScriptProperty]
		[Display(ResourceType = typeof(Custom.Resource), Name = "Period", GroupName = "NinjaScriptParameters", Order = 0)]
		public int Period { get; set; }
		#endregion
	}
}

