    INSERT INTO #NinjaTraderRagUpdate
    (Id, Title, FilePath, Language, Category, Tags, Content, Embedding, Description, RagLevel)
    VALUES
    (4422, N'Fix DashStyleHelper Does Not Exist Compile Error', N'DashStyleHelperMissingNamespace.cs', N'C#', N'Indicator', N'DashStyleHelper,CS0103,compile error,Draw.Line,Stroke,NinjaTrader.Gui,drawing tools,namespace,repair', N'#region Using declarations
using System.Windows.Media;
using NinjaTrader.Gui;
using NinjaTrader.Gui.Tools;
using NinjaTrader.NinjaScript.DrawingTools;
#endregion

// ERROR:
// CS0103: The name ''DashStyleHelper'' does not exist in the current context.
//
// CAUSE:
// DashStyleHelper belongs to the NinjaTrader.Gui namespace.
//
// FIX:
// Add:
// using NinjaTrader.Gui;

// Create a Line drawing object.
NinjaTrader.NinjaScript.DrawingTools.Line myLine =
    Draw.Line(
        this,
        "tag1",
        false,
        10,
        1000,
        0,
        1001,
        Brushes.LimeGreen,
        DashStyleHelper.Dot,
        2);

// Change the line Stroke.
myLine.Stroke = new Stroke(
    Brushes.Green,
    DashStyleHelper.Dash,
    5);

// REPAIR RULE:
// When code using DashStyleHelper produces CS0103,
// first ensure "using NinjaTrader.Gui;" is present.
