    (5422, N'High and Low Between Two Times', N'HighLowBetweenTimes.cs', N'C#', N'Indicator', N'high low between times,time range,session high low,opening range,Bars.GetBar,MAX,MIN,time window', N'#region Using declarations
using System;
using System.ComponentModel;
using System.ComponentModel.DataAnnotations;
using System.Windows.Media;
using System.Xml.Serialization;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SampleGetHighLowByTimeRange : Indicator
    {
        private DateTime startDateTime;
        private DateTime endDateTime;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Description = "Determines the highest high and lowest low in a specified intraday time range.";
                Name = "Sample Get High Low By Time Range";

                Calculate = Calculate.OnBarClose;
                IsOverlay = true;
                DisplayInDataBox = true;
                DrawOnPricePanel = true;
                DrawHorizontalGridLines = true;
                DrawVerticalGridLines = true;
                PaintPriceMarkers = true;
                ScaleJustification = NinjaTrader.Gui.Chart.ScaleJustification.Right;

                StartHour = 9;
                StartMinute = 30;
                EndHour = 10;
                EndMinute = 15;

                AddPlot(Brushes.Green, "HighestHigh");
                AddPlot(Brushes.Red, "LowestLow");
            }
        }

        protected override void OnBarUpdate()
        {
            // This example expects the end time to be later than the start time.
            if (EndHour < StartHour)
                return;

            // Wait until the requested time range has completed.
            if (ToTime(EndHour, EndMinute, 0) > ToTime(Time[0]))
                return;

            // Create the start and end DateTime values for the current bar date.
            if (startDateTime.Date != Time[0].Date)
            {
                startDateTime = new DateTime(
                    Time[0].Year,
                    Time[0].Month,
                    Time[0].Day,
                    StartHour,
                    StartMinute,
                    0);

                endDateTime = new DateTime(
                    Time[0].Year,
                    Time[0].Month,
                    Time[0].Day,
                    EndHour,
                    EndMinute,
                    0);
            }

            // Get the absolute bar indexes for the requested start and end times.
            int startBarIndex = Bars.GetBar(startDateTime);
            int endBarIndex = Bars.GetBar(endDateTime);

            // Include both the start and end bars in the calculation.
            int period = endBarIndex - startBarIndex + 1;

            // Convert the end bar index into a barsAgo value relative to CurrentBar.
            int endBarsAgo = CurrentBar - endBarIndex;

            double highestHigh = MAX(High, period)[endBarsAgo];
            double lowestLow = MIN(Low, period)[endBarsAgo];

            HighestHigh[0] = highestHigh;
            LowestLow[0] = lowestLow;
        }

        #region Properties

        [Browsable(false)]
        [XmlIgnore]
        public Series<double> HighestHigh
        {
            get { return Values[0]; }
        }

        [Browsable(false)]
        [XmlIgnore]
        public Series<double> LowestLow
        {
            get { return Values[1]; }
        }

        [Range(0, 23)]
        [NinjaScriptProperty]
        [Display(
            Name = "Start Hour",
            Description = "Start hour using 24-hour format, 0-23.",
            Order = 1,
            GroupName = "Parameters")]
        public int StartHour
        {
            get;
            set;
        }

        [Range(0, 59)]
        [NinjaScriptProperty]
        [Display(
            Name = "Start Minute",
            Description = "Start minute, 0-59.",
            Order = 2,
            GroupName = "Parameters")]
        public int StartMinute
        {
            get;
            set;
        }

        [Range(0, 23)]
        [NinjaScriptProperty]
        [Display(
            Name = "End Hour",
            Description = "End hour using 24-hour format, 0-23.",
            Order = 3,
            GroupName = "Parameters")]
        public int EndHour
        {
            get;
            set;
        }

        [Range(0, 59)]
        [NinjaScriptProperty]
        [Display(
            Name = "End Minute",
            Description = "End minute, 0-59.",
            Order = 4,
            GroupName = "Parameters")]
        public int EndMinute
        {
            get;
            set;
        }

        #endregion
