    (5424, N'Shade or Fill a Region Between Indicator Lines', N'FillRegionBetweenSeries.cs', N'C#', N'Indicator', N'shade between lines,fill between lines,chart region,indicator cloud,Draw.Region,opacity,Brushes', N'#region Using declarations
using System.ComponentModel.DataAnnotations;
using System.Windows.Media;
using NinjaTrader.NinjaScript;
using NinjaTrader.NinjaScript.DrawingTools;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SampleDrawRegion : Indicator
    {
        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Description = "Demonstrates shading regions between indicator series and price values.";
                Name = "Sample Draw Region";

                Calculate = Calculate.OnBarClose;
                IsOverlay = true;
                DisplayInDataBox = true;
                DrawOnPricePanel = true;
                DrawHorizontalGridLines = true;
                DrawVerticalGridLines = true;
                PaintPriceMarkers = true;
                ScaleJustification = NinjaTrader.Gui.Chart.ScaleJustification.Right;
                IsSuspendedWhileInactive = true;

                Period = 14;
                NumStdDev = 2;
            }
        }

        protected override void OnBarUpdate()
        {
            // Shade the area between the upper and middle Bollinger Bands.
            Draw.Region(
                this,
                "Bollinger Upper Region",
                CurrentBar,
                0,
                Bollinger(NumStdDev, Period).Upper,
                Bollinger(NumStdDev, Period).Middle,
                Brushes.Black,
                Brushes.Blue,
                20);

            // Shade the area between the lower and middle Bollinger Bands.
            Draw.Region(
                this,
                "Bollinger Lower Region",
                CurrentBar,
                0,
                Bollinger(NumStdDev, Period).Lower,
                Bollinger(NumStdDev, Period).Middle,
                Brushes.Black,
                Brushes.Blue,
                50);

            // Shade between an indicator series and a price value when
            // price closes above the upper Bollinger Band.
            if (Close[0] > Bollinger(NumStdDev, Period).Upper[0])
            {
                Draw.Region(
                    this,
                    "Upper Bollinger Broken " + CurrentBar,
                    1,
                    0,
                    Bollinger(NumStdDev, Period).Upper,
                    High[0],
                    Brushes.Black,
                    100);
            }
            // Shade between an indicator series and a price value when
            // price closes below the lower Bollinger Band.
            else if (Close[0] < Bollinger(NumStdDev, Period).Lower[0])
            {
                Draw.Region(
                    this,
                    "Lower Bollinger Broken " + CurrentBar,
                    1,
                    0,
                    Bollinger(NumStdDev, Period).Lower,
                    Low[0],
                    Brushes.Black,
                    100);
            }
        }

        #region Properties

        [Range(1, int.MaxValue)]
        [NinjaScriptProperty]
        [Display(
            Name = "Period",
            GroupName = "Parameters",
            Order = 0)]
        public int Period
        {
            get;
            set;
        }

        [Range(0, double.MaxValue)]
        [NinjaScriptProperty]
        [Display(
            Name = "Number Of Standard Deviations",
            GroupName = "Parameters",
            Order = 1)]
        public double NumStdDev
        {
            get;
            set;
        }

        #endregion
    }
