    (5432, N'Add User-Selectable Options to an Indicator', N'UserSelectableEnumOptions.cs', N'C#', N'Indicator', N'user options,dropdown,enum,switch,indicator parameter,moving average selector,SMA,EMA,HMA,WMA', N'#region Using declarations
using System;
using System.ComponentModel.DataAnnotations;
using System.Windows.Media;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SampleUniversalMovingAverage : Indicator
    {
        private CustomEnumNamespace.UniversalMovingAverage maType =
            CustomEnumNamespace.UniversalMovingAverage.SMA;

        private int period = 14;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Description = "Demonstrates a user-selectable moving average type.";
                Name = "Sample Universal Moving Average";

                Calculate = Calculate.OnBarClose;
                IsOverlay = true;

                AddPlot(Brushes.Orange, "MA");
            }
        }

        protected override void OnBarUpdate()
        {
            switch (MAType)
            {
                case CustomEnumNamespace.UniversalMovingAverage.EMA:
                    Value[0] = EMA(Period)[0];
                    break;

                case CustomEnumNamespace.UniversalMovingAverage.HMA:
                    Value[0] = HMA(Period)[0];
                    break;

                case CustomEnumNamespace.UniversalMovingAverage.SMA:
                    Value[0] = SMA(Period)[0];
                    break;

                case CustomEnumNamespace.UniversalMovingAverage.WMA:
                    Value[0] = WMA(Period)[0];
                    break;
            }
        }

        #region Properties

        [NinjaScriptProperty]
        [Display(
            Name = "Moving Average Type",
            Description = "Select the moving average used by the indicator.",
            GroupName = "Parameters",
            Order = 0)]
        public CustomEnumNamespace.UniversalMovingAverage MAType
        {
            get { return maType; }
            set { maType = value; }
        }

        [NinjaScriptProperty]
        [Range(1, int.MaxValue)]
        [Display(
            Name = "Period",
            Description = "Number of bars used for the moving average calculation.",
            GroupName = "Parameters",
            Order = 1)]
        public int Period
        {
            get { return period; }
            set { period = Math.Max(1, value); }
        }

        #endregion
    }
}

namespace CustomEnumNamespace
{
    public enum UniversalMovingAverage
    {
        EMA,
        HMA,
        SMA,
        WMA
    }
