    INSERT INTO #NinjaTraderRagUpdate
    (Id, Title, FilePath, Language, Category, Tags, Content, Embedding, Description, RagLevel)
    VALUES
    (5433, N'Access and Store Level II Order Book Data', N'Level2OrderBook.cs', N'C#', N'Indicator', N'Level II,order book,market depth,DOM,bid ask,liquidity,order flow,OnMarketDepth', N'#region Using declarations
using System.Collections.Generic;
using NinjaTrader.Cbi;
using NinjaTrader.Data;
using NinjaTrader.Gui.Chart;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SampleLevel2Book : Indicator
    {
        private readonly List<LadderRow> askRows = new List<LadderRow>(10);
        private readonly List<LadderRow> bidRows = new List<LadderRow>(10);

        private class LadderRow
        {
            public string MarketMaker;
            public double Price;
            public long Volume;
        }

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Description = "Demonstrates storing and reading Level II market depth data.";
                Name = "Sample Level II Book";

                Calculate = Calculate.OnEachTick;
                IsOverlay = false;
                DisplayInDataBox = true;
                DrawOnPricePanel = false;
                DrawHorizontalGridLines = true;
                DrawVerticalGridLines = true;
                PaintPriceMarkers = true;
                ScaleJustification = ScaleJustification.Right;
            }
        }

        protected override void OnBarUpdate()
        {
            // Example trigger: print the current Level II books when
            // price crosses above the 5-period SMA.
            if (!CrossAbove(Close, SMA(5), 1))
                return;

            ClearOutputWindow();

            Print("Ask Book");

            for (int index = 0; index < askRows.Count; index++)
            {
                Print(
                    "Ask Price=" + askRows[index].Price +
                    " Volume=" + askRows[index].Volume +
                    " Position=" + index);
            }

            Print("Bid Book");

            for (int index = 0; index < bidRows.Count; index++)
            {
                Print(
                    "Bid Price=" + bidRows[index].Price +
                    " Volume=" + bidRows[index].Volume +
                    " Position=" + index);
            }
        }

        protected override void OnMarketDepth(MarketDepthEventArgs e)
        {
            // Protect the live market depth collections against
            // concurrent/in-flight updates.
            lock (e.Instrument.SyncMarketDepth)
            {
                List<LadderRow> rows =
                    e.MarketDataType == MarketDataType.Ask
                        ? askRows
                        : bidRows;

                LadderRow row = new LadderRow
                {
                    MarketMaker = e.MarketMaker,
                    Price = e.Price,
                    Volume = e.Volume
                };

                if (e.Operation == Operation.Add ||
                    (e.Operation == Operation.Update &&
                     (rows.Count == 0 || rows.Count <= e.Position)))
                {
                    if (rows.Count <= e.Position)
                        rows.Add(row);
                    else
                        rows.Insert(e.Position, row);
                }
                else if (e.Operation == Operation.Remove &&
                         rows.Count > e.Position)
                {
                    rows.RemoveAt(e.Position);
                }
                else if (e.Operation == Operation.Update)
                {
                    if (rows[e.Position] == null)
                    {
                        rows[e.Position] = row;
                    }
                    else
                    {
                        rows[e.Position].MarketMaker = e.MarketMaker;
                        rows[e.Position].Price = e.Price;
                        rows[e.Position].Volume = e.Volume;
                    }
                }
            }
        }
