    (5434, N'Mark Trading Conditions and Highlight Trends on Chart', N'MarkConditionsAndTrends.cs', N'C#', N'Indicator', N'mark conditions,trend markers,highlight trend,draw diamond,draw rectangle,chart objects,Draw.Diamond,Draw.Rectangle', N'#region Using declarations
using System.Windows.Media;
using NinjaTrader.NinjaScript;
using NinjaTrader.NinjaScript.DrawingTools;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SampleDrawObject : Indicator
    {
        private int rectWidth;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Description = "Demonstrates marking trend changes and highlighting the current trend with drawing objects.";
                Name = "Sample Draw Object";
                Calculate = Calculate.OnBarClose;
                IsOverlay = true;
            }
        }

        protected override void OnBarUpdate()
        {
            // Mark the start of an uptrend when price crosses above the SMA.
            if (CrossAbove(Close, SMA(20), 1))
            {
                // Include CurrentBar in the tag to create a unique drawing object.
                Draw.Diamond(
                    this,
                    "UpDiamond" + CurrentBar,
                    false,
                    0,
                    SMA(20)[0],
                    Brushes.Blue);
            }
            // Mark the end of the uptrend when price crosses below the SMA.
            else if (CrossBelow(Close, SMA(20), 1))
            {
                Draw.Diamond(
                    this,
                    "DownDiamond" + CurrentBar,
                    false,
                    0,
                    SMA(20)[0],
                    Brushes.Magenta);
            }

            // Highlight the active uptrend with a rectangle.
            if (Close[0] >= SMA(20)[0])
            {
                /*
                 * Reusing the same drawing tag updates the existing rectangle
                 * instead of creating a new rectangle on every bar.
                 */
                Draw.Rectangle(
                    this,
                    "CurrentUptrend",
                    false,
                    rectWidth,
                    Close[rectWidth],
                    0,
                    Close[0],
                    Brushes.Blue,
                    Brushes.BlueViolet,
                    5);

                rectWidth++;
            }
            else
            {
                // Reset the width when the uptrend ends.
                rectWidth = 0;
            }
        }
    }
