    (5436, N'Expose Indicator Signals and Values to Other Scripts', N'ExposeIndicatorSignals.cs', N'C#', N'Indicator', N'expose indicator value,use indicator in strategy,bool signal,Series<bool>,bullish signal,bearish signal,public property', N'#region Using declarations
using System.ComponentModel;
using System.Windows.Media;
using System.Xml.Serialization;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SampleBoolSeries : Indicator
    {
        private Series<bool> bearIndication;
        private Series<bool> bullIndication;

        private double exposedVariable;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Bool Series";
                Calculate = Calculate.OnBarClose;
                IsOverlay = true;
            }
            else if (State == State.Configure)
            {
                // Synchronise each Series<bool> with the indicator''s bars.
                bullIndication = new Series<bool>(this);
                bearIndication = new Series<bool>(this);
            }
        }

        protected override void OnBarUpdate()
        {
            // Bullish MACD crossover.
            if (CrossAbove(MACD(12, 26, 9), MACD(12, 26, 9).Avg, 1))
            {
                BarBrushes[0] = Brushes.Lime;

                bullIndication[0] = true;
                bearIndication[0] = false;
            }
            // Bearish MACD crossover.
            else if (CrossBelow(MACD(12, 26, 9), MACD(12, 26, 9).Avg, 1))
            {
                BarBrushes[0] = Brushes.Magenta;

                bullIndication[0] = false;
                bearIndication[0] = true;
            }
            else
            {
                bullIndication[0] = false;
                bearIndication[0] = false;
            }

            // Example of exposing a non-Series value.
            exposedVariable = Close[0];
        }

        #region Properties

        // Expose the bullish signal for use by another indicator or strategy.
        [Browsable(false)]
        [XmlIgnore]
        public Series<bool> BullIndication
        {
            get { return bullIndication; }
        }

        // Expose the bearish signal for use by another indicator or strategy.
        [Browsable(false)]
        [XmlIgnore]
        public Series<bool> BearIndication
        {
            get { return bearIndication; }
        }

        // For a normal variable rather than a Series, call Update()
        // before returning it so the hosted indicator is current.
        [Browsable(false)]
        public double ExposedVariable
        {
            get
            {
                Update();
                return exposedVariable;
            }
        }

        #endregion
    }
