    INSERT INTO #NinjaTraderRagUpdate
    (Id, Title, FilePath, Language, Category, Tags, Content, Embedding, Description, RagLevel)
    VALUES
    (5438, N'Get an Indicator Value from a Specific Time', N'GetIndicatorValueAtTime.cs', N'C#', N'Indicator', N'specific time,historical value,previous day,find bar by time,Bars.GetBar,bars ago,indicator value,SMA', N'#region Using declarations
using System;
using System.ComponentModel;
using System.ComponentModel.DataAnnotations;
using System.Windows.Media;
using System.Xml.Serialization;
using NinjaTrader.Gui;
using NinjaTrader.NinjaScript;
using NinjaTrader.NinjaScript.DrawingTools;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SampleGetBar : Indicator
    {
        private DateTime timeOfInterest;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Description = "Demonstrates retrieving an indicator value from a specific historical time.";
                Name = "Sample Get Bar";

                Calculate = Calculate.OnBarClose;
                IsOverlay = true;

                SMAPeriod = 14;

                AddPlot(Brushes.Orange, "SMAPlot");
            }
        }

        protected override void OnBarUpdate()
        {
            // Store the current SMA value in the indicator plot.
            SMAPlot[0] = SMA(SMAPeriod)[0];

            /*
             * At the beginning of each session, create a DateTime for
             * 9:30 AM on the previous trading day.
             *
             * This simplified example assumes Monday-Friday sessions.
             */
            if (Bars.IsFirstBarOfSession && IsFirstTickOfBar)
            {
                DateTime todayAt930 = new DateTime(
                    Time[0].Year,
                    Time[0].Month,
                    Time[0].Day,
                    9,
                    30,
                    0);

                // On Monday, use the previous Friday.
                if (Time[0].DayOfWeek == DayOfWeek.Monday)
                    timeOfInterest = todayAt930.AddDays(-3);
                else
                    timeOfInterest = todayAt930.AddDays(-1);
            }

            /*
             * Bars.GetBar() returns the bar index associated with the
             * requested DateTime.
             *
             * Convert that absolute bar index into a barsAgo value so
             * the historical indicator value can be accessed.
             */
            int targetBarIndex = Bars.GetBar(timeOfInterest);
            int barsAgo = CurrentBar - targetBarIndex;

            if (barsAgo > 0 && barsAgo <= CurrentBar && CurrentBar > 10)
            {
                double historicalSma = SMAPlot[barsAgo];

                // Draw the historical SMA value across the recent chart.
                Draw.Line(
                    this,
                    "PreviousDaySMA",
                    true,
                    10,
                    historicalSma,
                    0,
                    historicalSma,
                    Brushes.Red,
                    DashStyleHelper.Solid,
                    5);
            }
        }

        #region Properties

        [Browsable(false)]
        [XmlIgnore]
        public Series<double> SMAPlot
        {
            get { return Values[0]; }
        }

        [Range(1, int.MaxValue)]
        [NinjaScriptProperty]
        [Display(
            Name = "SMA Period",
            Description = "Period used for the simple moving average.",
            GroupName = "Parameters",
            Order = 0)]
        public int SMAPeriod
        {
            get;
            set;
        }

        #endregion
    }
