    (5439, N'Use Date and Time in Trading Logic', N'DateTimeTradingLogic.cs', N'C#', N'Indicator', N'time filter,trading hours,DateTime,time condition,compare times,add minutes,time range,TimeSpan', N'#region Using declarations
using System;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SampleDateTimeFunctions : Indicator
    {
        private DateTime myDateTime;
        private DateTime adjustedDateTime;
        private TimeSpan timeOffset;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Description = "Demonstrates common DateTime operations for time-based trading logic.";
                Name = "Sample DateTime Functions";

                Calculate = Calculate.OnPriceChange;
                IsOverlay = false;

                // Example offset of 3 minutes and 2 seconds.
                timeOffset = new TimeSpan(0, 3, 2);
            }
        }

        protected override void OnBarUpdate()
        {
            if (CurrentBar != 0)
                return;

            // Parse a date and time from text.
            string dateTimeToParse = "07/29/2009 14:30:00";

            if (!DateTime.TryParse(dateTimeToParse, out myDateTime))
            {
                Print("Unable to parse DateTime.");
                return;
            }

            // Access individual date and time components.
            int year = myDateTime.Year;
            int month = myDateTime.Month;
            int day = myDateTime.Day;
            int hour = myDateTime.Hour;
            int minute = myDateTime.Minute;
            int second = myDateTime.Second;

            // Format a DateTime for display.
            string formattedTime =
                myDateTime.ToString("yyyy-MM-dd HH:mm:ss");

            Print("Formatted time: " + formattedTime);

            // Add a TimeSpan to an existing DateTime.
            adjustedDateTime = myDateTime.Add(timeOffset);

            // DateTime can also be adjusted directly.
            adjustedDateTime = adjustedDateTime.AddMinutes(5);
            adjustedDateTime = adjustedDateTime.AddSeconds(4);

            // Compare two DateTime values.
            int comparison = DateTime.Compare(
                myDateTime,
                adjustedDateTime);

            if (comparison < 0)
                Print("Original time is earlier.");
            else if (comparison > 0)
                Print("Original time is later.");
            else
                Print("Times are equal.");

            // Bar timestamps can also be compared with DateTime values.
            DateTime barTime = Time[0];

            if (barTime.TimeOfDay >= new TimeSpan(9, 30, 0)
                && barTime.TimeOfDay <= new TimeSpan(16, 0, 0))
            {
                Print("Bar is inside the selected trading hours.");
            }
        }
    }
