    (5440, N'Split, Find and Replace Text Strings', N'StringFunctions.cs', N'C#', N'Indicator', N'string,text,split string,find text,replace text,escape characters,IndexOf,Replace', N'#region Using declarations
using System;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SampleStringFunctions : Indicator
    {
        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Description = "Demonstrates common string and text manipulation operations.";
                Name = "Sample String Functions";
                Calculate = Calculate.OnPriceChange;
                IsOverlay = false;
            }
        }

        protected override void OnBarUpdate()
        {
            if (CurrentBar != 0)
                return;

            ClearOutputWindow();

            // Escaped and verbatim strings can represent the same file path.
            string verbatimPath = @"C:\NinjaTrader 8\bin";
            string escapedPath = "C:\\NinjaTrader 8\\bin";

            Print(verbatimPath);
            Print(escapedPath);

            // Split a string into separate words.
            string text = "NinjaTrader is a trading platform.";
            string[] words = text.Split('' '');

            foreach (string word in words)
                Print(word);

            // Find the position of text within another string.
            string phrase = "Like finding a needle in a haystack.";
            int index = phrase.IndexOf("needle");

            Print("Index of needle: " + index);

            // Replace part of a string with different text.
            string updatedPhrase = phrase.Replace(
                "haystack",
                "some big field");

            Print(updatedPhrase);

            // Escape quotation marks when they are part of a string.
            string message = "Trader said, \"Enter long.\"";

            Print(message);
        }
    }
