    (5441, N'Change Plot Color When Indicator Is Rising or Falling', N'DynamicPlotColors.cs', N'C#', N'Indicator', N'change plot color,multi color plot,rising falling,trend color,PlotBrushes,IsRising,IsFalling', N'#region Using declarations
using System;
using System.ComponentModel.DataAnnotations;
using System.Windows.Media;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SampleMultiColoredPlot : Indicator
    {
        private Series<double> middle;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Description = "Demonstrates changing plot colors based on whether indicator values are rising, falling or neutral.";
                Name = "Sample Multi Colored Plot";

                Calculate = Calculate.OnBarClose;
                IsOverlay = true;

                Period = 14;

                AddPlot(Brushes.SkyBlue, "Upper");
                AddPlot(Brushes.SkyBlue, "Lower");

                Plots[0].Width = 2;
                Plots[1].Width = 2;
            }
            else if (State == State.Configure)
            {
                middle = new Series<double>(this);
            }
        }

        protected override void OnBarUpdate()
        {
            if (CurrentBar < Period)
                return;

            // Calculate upper and lower moving-average plots.
            Upper[0] = SMA(High, Period)[0];
            Lower[0] = SMA(Low, Period)[0];

            // Use the midpoint to determine whether the indicator is
            // rising, falling or unchanged.
            middle[0] = (Upper[0] + Lower[0]) / 2.0;

            if (IsRising(middle))
            {
                // Rising condition.
                PlotBrushes[0][0] = Brushes.Black;
                PlotBrushes[1][0] = Brushes.LimeGreen;
            }
            else if (IsFalling(middle))
            {
                // Falling condition.
                PlotBrushes[0][0] = Brushes.Red;
                PlotBrushes[1][0] = Brushes.Black;
            }
            else
            {
                // Neutral condition.
                PlotBrushes[0][0] = Brushes.Blue;
                PlotBrushes[1][0] = Brushes.Blue;
            }
        }

        #region Properties

        [Range(1, int.MaxValue)]
        [NinjaScriptProperty]
        [Display(
            Name = "Period",
            Description = "Moving average period.",
            GroupName = "Parameters",
            Order = 0)]
        public int Period
        {
            get;
            set;
        }

        [Browsable(false)]
        public Series<double> Upper
        {
            get { return Values[0]; }
        }

        [Browsable(false)]
        public Series<double> Lower
        {
            get { return Values[1]; }
        }

        #endregion
    }
