    (5442, N'Customize or Shorten the Chart Label', N'CustomDisplayName.cs', N'C#', N'Indicator', N'shorten chart label,custom label,indicator name,hide parameters,DisplayName,chart display name', N'#region Using declarations
using System.ComponentModel.DataAnnotations;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SampleDisplayName : Indicator
    {
        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Description = "Demonstrates customizing the label displayed for a NinjaScript item.";
                Name = "Sample Display Name";

                Calculate = Calculate.OnBarClose;
                IsOverlay = false;

                Period = 5;
                Interval = 10;
                Smooth = 15;
                NumStdDev = 2;
            }
        }

        protected override void OnBarUpdate()
        {
        }

        // Override DisplayName to control what is shown on the chart.
        // Only the most important parameters need to be displayed.
        public override string DisplayName
        {
            get
            {
                return Name + "(" + Period + "," + Interval + ")";
            }
        }

        #region Properties

        [Range(1, int.MaxValue)]
        [NinjaScriptProperty]
        [Display(
            Name = "Period",
            GroupName = "Parameters",
            Order = 0)]
        public int Period
        {
            get;
            set;
        }

        [Range(1, int.MaxValue)]
        [NinjaScriptProperty]
        [Display(
            Name = "Interval",
            GroupName = "Parameters",
            Order = 1)]
        public int Interval
        {
            get;
            set;
        }

        [Range(1, int.MaxValue)]
        [NinjaScriptProperty]
        [Display(
            Name = "Smooth",
            GroupName = "Parameters",
            Order = 2)]
        public int Smooth
        {
            get;
            set;
        }

        [Range(1, int.MaxValue)]
        [NinjaScriptProperty]
        [Display(
            Name = "Standard Deviations",
            GroupName = "Parameters",
            Order = 3)]
        public int NumStdDev
        {
            get;
            set;
        }

        #endregion
    }
