    INSERT INTO #NinjaTraderRagUpdate
    (Id, Title, FilePath, Language, Category, Tags, Content, Embedding, Description, RagLevel)
    VALUES
    (5443, N'Use a Secondary Timeframe as Indicator Input', N'SecondarySeriesAsIndicatorInput.cs', N'C#', N'Indicator', N'higher timeframe,multi timeframe,secondary series,AddDataSeries,BarsArray,BarsInProgress,indicator input', N'#region Using declarations
using System.ComponentModel;
using System.Windows.Media;
using System.Xml.Serialization;
using NinjaTrader.Data;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SampleSecondarySeriesAsInputSeries : Indicator
    {
        private SMA primarySma;
        private SMA secondarySma;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Description = "Demonstrates using a secondary data series as input to an indicator.";
                Name = "Sample Secondary Series As Input Series";

                Calculate = Calculate.OnBarClose;
                IsOverlay = true;
                DisplayInDataBox = true;
                BarsRequiredToPlot = 14;

                AddPlot(Brushes.Blue, "SMA Primary Series");
                AddPlot(Brushes.Green, "SMA Secondary Series");
            }
            else if (State == State.Configure)
            {
                // Add a secondary 5-minute data series.
                AddDataSeries(BarsPeriodType.Minute, 5);
            }
            else if (State == State.DataLoaded)
            {
                // Create an SMA using the primary chart series.
                primarySma = SMA(BarsArray[0], 14);

                // Create an SMA using the secondary 5-minute series.
                secondarySma = SMA(BarsArray[1], 14);
            }
        }

        protected override void OnBarUpdate()
        {
            // Ensure both data series contain enough data before accessing them.
            if (CurrentBars[0] < 1 || CurrentBars[1] < 1)
                return;

            // Process updates from the secondary 5-minute series.
            if (BarsInProgress == 1)
            {
                SMASecondary[0] = secondarySma[0];
                return;
            }

            // Process updates from the primary series.
            if (BarsInProgress == 0)
            {
                SMAPrimary[0] = primarySma[0];

                // If the secondary series has not produced a new value on
                // this primary bar, carry forward its previous value.
                if (!SMASecondary.IsValidDataPoint(0))
                    SMASecondary[0] = SMASecondary[1];
            }
        }

        #region Properties

        [Browsable(false)]
        [XmlIgnore]
        public Series<double> SMAPrimary
        {
            get { return Values[0]; }
        }

        [Browsable(false)]
        [XmlIgnore]
        public Series<double> SMASecondary
        {
            get { return Values[1]; }
        }

        #endregion
    }
