    (5444, N'Store Custom Values for Each Bar', N'CustomSeriesValues.cs', N'C#', N'Indicator', N'store values,custom series,Series<T>,per bar data,historical values,intermediate calculations,indicator input', N'#region Using declarations
using System;
using System.ComponentModel.DataAnnotations;
using System.Windows.Media;
using NinjaTrader.Gui.Chart;
using NinjaTrader.Gui.Tools;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SampleCustomSeries : Indicator
    {
        private Series<double> myDoubleSeries;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Description = "Demonstrates storing custom values for each bar using Series<T>.";
                Name = "Sample Custom Series";

                Calculate = Calculate.OnBarClose;
                IsOverlay = false;

                Period = 5;

                AddPlot(
                    new Stroke(Brushes.Orange, 1),
                    PlotStyle.Bar,
                    "Average Range");
            }
            else if (State == State.DataLoaded)
            {
                // Create a Series<double> synchronized with the script''s bars.
                myDoubleSeries = new Series<double>(this);
            }
        }

        protected override void OnBarUpdate()
        {
            // Store a custom value for the current bar.
            myDoubleSeries[0] = Math.Abs(Close[0] - Open[0]);

            // Historical values can be retrieved using barsAgo indexing.
            // Example:
            // double previousValue = myDoubleSeries[1];

            // A custom Series<double> can also be supplied as the
            // input series to another indicator.
            Value[0] = SMA(myDoubleSeries, Period)[0];
        }

        #region Properties

        [Range(1, int.MaxValue)]
        [NinjaScriptProperty]
        [Display(
            Name = "Period",
            Description = "Period used to average the custom series values.",
            GroupName = "Parameters",
            Order = 0)]
        public int Period
        {
            get;
            set;
        }

        #endregion
    }
