    (5445, N'Show or Hide Indicator Settings Dynamically', N'ShowHideProperties.cs', N'C#', N'Indicator', N'show hide setting,conditional property,optional settings,TypeConverter,property grid', N'[TypeConverter("NinjaTrader.NinjaScript.Indicators.MyConverter")]
public class SampleIndicator : Indicator
{
    [RefreshProperties(RefreshProperties.All)]
    [Display(Name = "Show advanced settings")]
    public bool ShowAdvanced
    { get; set; }

    [Display(Name = "Advanced period")]
    public int AdvancedPeriod
    { get; set; }
}

public class MyConverter : IndicatorBaseConverter
{
    public override PropertyDescriptorCollection GetProperties(
        ITypeDescriptorContext context,
        object component,
        Attribute[] attributes)
    {
        PropertyDescriptorCollection properties =
            base.GetProperties(context, component, attributes);

        SampleIndicator indicator = component as SampleIndicator;

        if (indicator == null || indicator.ShowAdvanced)
            return properties;

        PropertyDescriptor advanced =
            properties["AdvancedPeriod"];

        if (advanced != null)
            properties.Remove(advanced);

        return properties;
    }

    public override bool GetPropertiesSupported(
        ITypeDescriptorContext context)
    {
        return true;
    }
