    (5447, N'Display Friendly Yes/No Options Instead of a Checkbox', N'FriendlyBooleanDropdown.cs', N'C#', N'Indicator', N'dropdown setting,on off,boolean option,friendly setting,TypeConverter', N'[TypeConverter(typeof(FriendlyBoolConverter))]
[PropertyEditor("NinjaTrader.Gui.Tools.StringStandardValuesEditorKey")]
[Display(Name = "Feature enabled")]
public bool FeatureEnabled
{ get; set; }

public class FriendlyBoolConverter : TypeConverter
{
    public override StandardValuesCollection GetStandardValues(
        ITypeDescriptorContext context)
    {
        return new StandardValuesCollection(
            new[] { "On", "Off" });
    }

    public override object ConvertFrom(
        ITypeDescriptorContext context,
        CultureInfo culture,
        object value)
    {
        return value.ToString() == "On";
    }

    public override object ConvertTo(
        ITypeDescriptorContext context,
        CultureInfo culture,
        object value,
        Type destinationType)
    {
        return (bool)value ? "On" : "Off";
    }

    public override bool GetStandardValuesExclusive(
        ITypeDescriptorContext context) => true;

    public override bool GetStandardValuesSupported(
        ITypeDescriptorContext context) => true;
