    INSERT INTO #NinjaTraderRagUpdate
    (Id, Title, FilePath, Language, Category, Tags, Content, Embedding, Description, RagLevel)
    VALUES
    (5448, N'Display Friendly Names for Enum Options', N'FriendlyEnumDropdown.cs', N'C#', N'Indicator', N'enum dropdown,friendly names,select option,custom dropdown,TypeConverter', N'public enum TradeMode
{
    TrendFollowing,
    MeanReversion,
    Breakout
}

[TypeConverter(typeof(TradeModeConverter))]
[PropertyEditor("NinjaTrader.Gui.Tools.StringStandardValuesEditorKey")]
[Display(Name = "Trading mode")]
public TradeMode Mode
{ get; set; }

public class TradeModeConverter : TypeConverter
{
    public override StandardValuesCollection GetStandardValues(
        ITypeDescriptorContext context)
    {
        return new StandardValuesCollection(
            new[]
            {
                "Trend Following",
                "Mean Reversion",
                "Breakout"
            });
    }

    public override object ConvertFrom(
        ITypeDescriptorContext context,
        CultureInfo culture,
        object value)
    {
        switch (value.ToString())
        {
            case "Trend Following":
                return TradeMode.TrendFollowing;

            case "Mean Reversion":
                return TradeMode.MeanReversion;

            case "Breakout":
                return TradeMode.Breakout;

            default:
                return TradeMode.TrendFollowing;
        }
    }

    public override object ConvertTo(
        ITypeDescriptorContext context,
        CultureInfo culture,
        object value,
        Type destinationType)
    {
        switch ((TradeMode)value)
        {
            case TradeMode.TrendFollowing:
                return "Trend Following";

            case TradeMode.MeanReversion:
                return "Mean Reversion";

            case TradeMode.Breakout:
                return "Breakout";

            default:
                return string.Empty;
        }
    }

    public override bool GetStandardValuesExclusive(
        ITypeDescriptorContext context) => true;

    public override bool GetStandardValuesSupported(
        ITypeDescriptorContext context) => true;
