    (5449, N'Allow Users to Edit a List of Custom Values', N'EditableValueCollection.cs', N'C#', N'Indicator', N'editable list,custom values,collection editor,user levels,PropertyEditor,ICloneable', N'[CategoryDefaultExpanded(true)]
public class PercentValue : NotifyPropertyChangedBase, ICloneable
{
    public PercentValue()
    {
    }

    public PercentValue(double value)
    {
        Value = value;
    }

    [Display(Name = "Value (%)")]
    public double Value
    { get; set; }

    public object Clone()
    {
        return new PercentValue(Value);
    }

    public override string ToString()
    {
        return Value.ToString(CultureInfo.InvariantCulture) + " %";
    }
}

