    (5450, N'Run Logic on a Timer Without Waiting for a Bar', N'TimerCustomEvent.cs', N'C#', N'Indicator', N'timer event,run every second,custom event,TriggerCustomEvent,periodic logic,without bar update', N'#region Using declarations
using System;
using System.Timers;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SampleCustomEvents : Indicator
    {
        private Timer timer;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Description = "Demonstrates running NinjaScript logic from a timer using TriggerCustomEvent.";
                Name = "Sample Custom Events";

                Calculate = Calculate.OnBarClose;
                IsOverlay = true;
            }
            else if (State == State.DataLoaded)
            {
                // Trigger an event every second.
                timer = new Timer(1000);
                timer.Elapsed += TimerElapsed;
                timer.Start();
            }
            else if (State == State.Terminated)
            {
                if (timer != null)
                {
                    timer.Stop();
                    timer.Elapsed -= TimerElapsed;
                    timer.Dispose();
                    timer = null;
                }
            }
        }

        protected override void OnBarUpdate()
        {
            // Normal bar or tick processing can remain here.
        }

        private void TimerElapsed(object sender, ElapsedEventArgs e)
        {
            // Do not directly process NinjaScript data from the timer thread.
            // TriggerCustomEvent safely transfers processing back to NinjaScript.
            TriggerCustomEvent(
                ProcessTimerEvent,
                timer.Interval);
        }

        private void ProcessTimerEvent(object state)
        {
            double interval = (double)state;

            Print("Timer event: " + DateTime.Now);
            Print("Interval: " + interval + " ms");

            // Access or process NinjaScript data here.
        }
    }
