    (5451, N'Read External Data from a Text or CSV File', N'ReadExternalData.cs', N'C#', N'Indicator', N'read file,CSV data,text file,external data,StreamReader,import data,OHLC', N'#region Using declarations
using System;
using System.IO;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SampleStreamReader : Indicator
    {
        private string filePath;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Description = "Demonstrates reading external OHLC data from a text or CSV file.";
                Name = "Sample Stream Reader";
                Calculate = Calculate.OnBarClose;

                filePath = NinjaTrader.Core.Globals.UserDataDir + "MyTestFile.txt";
            }
        }

        protected override void OnBarUpdate()
        {
            if (!File.Exists(filePath))
            {
                Print("File does not exist.");
                return;
            }

            double currentOpen = 0;
            double currentHigh = double.MinValue;
            double currentLow = double.MaxValue;
            double currentClose = 0;
            bool openFound = false;

            try
            {
                using (StreamReader reader = new StreamReader(filePath))
                {
                    string line;

                    while ((line = reader.ReadLine()) != null)
                    {
                        // Expected format:
                        // Date,Open,High,Low,Close
                        string[] values = line.Split('','');

                        if (values.Length < 5)
                            continue;

                        DateTime dataTime = DateTime.Parse(values[0]);

                        // Only process records matching the current bar date.
                        if (ToDay(dataTime) != ToDay(Time[0]))
                            continue;

                        double open = double.Parse(values[1]);
                        double high = double.Parse(values[2]);
                        double low = double.Parse(values[3]);
                        double close = double.Parse(values[4]);

                        if (!openFound)
                        {
                            currentOpen = open;
                            openFound = true;
                        }

                        if (high > currentHigh)
                            currentHigh = high;

                        if (low < currentLow)
                            currentLow = low;

                        currentClose = close;
                    }
                }

                if (openFound)
                {
                    Print(
                        "Current Day OHLC: "
                        + currentOpen + " "
                        + currentHigh + " "
                        + currentLow + " "
                        + currentClose);
                }
            }
            catch (Exception error)
            {
                Print("Error reading file: " + error.Message);
            }
        }
    }
