    (5452, N'Save Trading Data to a Text or CSV File', N'WriteDataToFile.cs', N'C#', N'Indicator', N'save to file,export data,CSV file,write text,StreamWriter,trade log,OHLC', N'#region Using declarations
using System.IO;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SampleStreamWriter : Indicator
    {
        private string filePath;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Description = "Demonstrates exporting bar data to a text or CSV file.";
                Name = "Sample Stream Writer";

                Calculate = Calculate.OnBarClose;

                filePath =
                    NinjaTrader.Core.Globals.UserDataDir
                    + "MarketData.csv";
            }
        }

        protected override void OnBarUpdate()
        {
            // Append one CSV row containing:
            // Time, Open, High, Low, Close.
            using (StreamWriter writer = File.AppendText(filePath))
            {
                writer.WriteLine(
                    Time[0] + ","
                    + Open[0] + ","
                    + High[0] + ","
                    + Low[0] + ","
                    + Close[0]);
            }
        }
    }
