    INSERT INTO #NinjaTraderRagUpdate
    (Id, Title, FilePath, Language, Category, Tags, Content, Embedding, Description, RagLevel)
    VALUES
    (5453, N'Quickly Read and Write Small Text Files', N'SimpleFileReadWrite.cs', N'C#', N'Indicator', N'read write file,save data,load data,text file,AppendAllText,ReadAllText,small file', N'#region Using declarations
using System;
using System.IO;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SampleFileReadWrite : Indicator
    {
        private string filePath;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Description = "Demonstrates simple file read and write operations.";
                Name = "Sample File Read Write";
                Calculate = Calculate.OnBarClose;

                filePath =
                    NinjaTrader.Core.Globals.UserDataDir
                    + "MarketData.txt";
            }
        }

        protected override void OnBarUpdate()
        {
            // Save one line of OHLC data.
            string line =
                ToDay(Time[0]) + ","
                + Open[0] + ","
                + High[0] + ","
                + Low[0] + ","
                + Close[0]
                + Environment.NewLine;

            File.AppendAllText(filePath, line);

            // Read the complete file back into memory.
            string fileContents = File.ReadAllText(filePath);

            // Split the stored data into separate lines.
            string[] lines = fileContents.Split(
                new[] { ''\r'', ''\n'' },
                StringSplitOptions.RemoveEmptyEntries);

            if (lines.Length == 0)
                return;

            // Parse the most recent saved row.
            string[] values = lines[lines.Length - 1].Split('','');

            if (values.Length < 5)
                return;

            int date = int.Parse(values[0]);
            double open = double.Parse(values[1]);
            double high = double.Parse(values[2]);
            double low = double.Parse(values[3]);
            double close = double.Parse(values[4]);

            Print(
                "Stored OHLC: "
                + date + " "
                + open + " "
                + high + " "
                + low + " "
                + close);
        }
    }
