    (5454, N'Catch and Log Runtime Errors', N'TryCatchRuntimeErrors.cs', N'C#', N'Indicator', N'try catch,runtime error,exception handling,debug error,Log,Print', N'#region Using declarations
using System;
using System.Windows.Media;
using NinjaTrader.Cbi;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SampleTryCatch : Indicator
    {
        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Description = "Demonstrates catching and logging runtime exceptions.";
                Name = "Sample Try Catch";

                Calculate = Calculate.OnBarClose;
                IsOverlay = true;

                AddPlot(Brushes.Orange, "Moving Average");
            }
        }

        protected override void OnBarUpdate()
        {
            try
            {
                int period = 10;
                double closeSum = 0;

                while (period > 0)
                {
                    // This may throw an exception when there are not
                    // enough historical bars available.
                    closeSum += Close[period];
                    period--;
                }

                Value[0] = closeSum / 10;
            }
            catch (Exception exception)
            {
                if (State >= State.Terminated)
                    return;

                Log(
                    "Runtime error in SampleTryCatch.",
                    LogLevel.Warning);

                Print(
                    Time[0]
                    + " "
                    + exception);
            }
        }
    }
