    (5455, N'Add a Custom Button to a Chart', N'AddChartButton.cs', N'C#', N'Indicator', N'chart button,custom button,WPF,toolbar,ChartControl,button click', N'private Button chartButton;
private Grid chartGrid;

protected override void OnStateChange()
{
    if (State == State.Historical && ChartControl != null)
    {
        ChartControl.Dispatcher.InvokeAsync(() =>
        {
            Chart chartWindow =
                Window.GetWindow(ChartControl.Parent) as Chart;

            if (chartWindow == null)
                return;

            chartGrid = chartWindow.MainTabControl.Parent as Grid;

            chartButton = new Button
            {
                Content = "My Button",
                Margin = new Thickness(2)
            };

            chartButton.Click += ChartButton_Click;

            chartGrid.Children.Add(chartButton);
        });
    }
    else if (State == State.Terminated && ChartControl != null)
    {
        ChartControl.Dispatcher.InvokeAsync(() =>
        {
            if (chartButton != null)
            {
                chartButton.Click -= ChartButton_Click;
                chartGrid?.Children.Remove(chartButton);
            }
        });
    }
}

private void ChartButton_Click(
    object sender,
    RoutedEventArgs e)
{
    Print("Custom chart button clicked.");
