    (5456, N'Add a Custom Side Panel to a Chart', N'AddChartSidePanel.cs', N'C#', N'Indicator', N'side panel,chart panel,WPF controls,custom UI,buttons,GridSplitter', N'private Grid sidePanel;
private Grid chartGrid;

private void AddSidePanel()
{
    Chart chartWindow =
        Window.GetWindow(ChartControl.Parent) as Chart;

    if (chartWindow == null)
        return;

    chartGrid = chartWindow.MainTabControl.Parent as Grid;

    int chartColumn =
        Grid.GetColumn(chartWindow.MainTabControl);

    chartGrid.ColumnDefinitions.Insert(
        chartColumn + 1,
        new ColumnDefinition
        {
            Width = new GridLength(
                200,
                GridUnitType.Pixel)
        });

    sidePanel = new Grid();

    sidePanel.RowDefinitions.Add(
        new RowDefinition());

    Button button = new Button
    {
        Content = "Action",
        Margin = new Thickness(5)
    };

    sidePanel.Children.Add(button);

    Grid.SetColumn(
        sidePanel,
        chartColumn + 1);

    Grid.SetRow(
        sidePanel,
        Grid.GetRow(chartWindow.MainTabControl));

    chartGrid.Children.Add(sidePanel);
