    (5457, N'Add Custom Buttons to Chart Trader', N'AddChartTraderButtons.cs', N'C#', N'Indicator', N'Chart Trader,custom button,trade button,WPF,order controls,ChartTrader', N'private Grid chartTraderGrid;
private Button customButton;

private void AddChartTraderButton()
{
    Chart chartWindow =
        Window.GetWindow(ChartControl.Parent) as Chart;

    if (chartWindow == null)
        return;

    ChartTrader chartTrader =
        chartWindow.FindFirst(
            "ChartWindowChartTraderControl")
        as ChartTrader;

    if (chartTrader == null)
        return;

    chartTraderGrid =
        chartTrader.Content as Grid;

    if (chartTraderGrid == null)
        return;

    chartTraderGrid.RowDefinitions.Add(
        new RowDefinition
        {
            Height = new GridLength(30)
        });

    customButton = new Button
    {
        Content = "Custom Action"
    };

    customButton.Click += CustomButton_Click;

    Grid.SetRow(
        customButton,
        chartTraderGrid.RowDefinitions.Count - 1);

    chartTraderGrid.Children.Add(customButton);
}

private void CustomButton_Click(
    object sender,
    RoutedEventArgs e)
{
    Print("Chart Trader button clicked.");
