    INSERT INTO #NinjaTraderRagUpdate
    (Id, Title, FilePath, Language, Category, Tags, Content, Embedding, Description, RagLevel)
    VALUES
    (5458, N'Modify Existing Chart Trader Buttons', N'ModifyChartTraderButtons.cs', N'C#', N'Indicator', N'Chart Trader,buy button,sell button,modify button,custom trade controls,FindFirst', N'private Button buyMarketButton;
private Button sellMarketButton;

private void FindChartTraderButtons()
{
    Chart chartWindow =
        Window.GetWindow(ChartControl.Parent) as Chart;

    if (chartWindow == null)
        return;

    ChartTrader chartTrader =
        chartWindow.FindFirst(
            "ChartWindowChartTraderControl")
        as ChartTrader;

    if (chartTrader == null)
        return;

    Grid chartTraderGrid =
        chartTrader.Content as Grid;

    buyMarketButton =
        chartTraderGrid.FindFirst(
            "ChartTraderControlQuickBuyMarketButton")
        as Button;

    sellMarketButton =
        chartTraderGrid.FindFirst(
            "ChartTraderControlQuickSellMarketButton")
        as Button;

    if (buyMarketButton != null)
        buyMarketButton.Background = Brushes.Green;

    if (sellMarketButton != null)
        sellMarketButton.Background = Brushes.Red;
