    (5459, N'Add a Custom Menu to the Chart Window', N'AddChartMenu.cs', N'C#', N'Indicator', N'chart menu,custom menu,menu item,WPF,chart controls,NTMenuItem', N'private Menu customMenu;
private NTMenuItem menuItem;

private void AddChartMenu()
{
    Chart chartWindow =
        Window.GetWindow(ChartControl.Parent) as Chart;

    if (chartWindow == null)
        return;

    customMenu = new Menu();

    menuItem = new NTMenuItem
    {
        Header = "My Tools"
    };

    NTMenuItem actionItem =
        new NTMenuItem
        {
            Header = "Run Action"
        };

    actionItem.Click += MenuItem_Click;

    menuItem.Items.Add(actionItem);
    customMenu.Items.Add(menuItem);

    chartWindow.MainMenu.Add(customMenu);
}

private void MenuItem_Click(
    object sender,
    RoutedEventArgs e)
{
    Print("Custom menu action selected.");
