    (5460, N'Use a Lower Timeframe for Intrabar Backtest Fills', N'IntrabarOrderFills.cs', N'C#', N'Strategy', N'intrabar fill,backtest fills,lower timeframe,secondary series,AddDataSeries,BarsInProgress,EnterLong,EnterShort', N'#region Using declarations
using NinjaTrader.Data;
using NinjaTrader.NinjaScript;
using NinjaTrader.NinjaScript.Indicators;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleIntrabarBacktest : Strategy
    {
        private EMA fastEma;
        private EMA slowEma;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Intrabar Backtest";
                Calculate = Calculate.OnBarClose;
            }
            else if (State == State.Configure)
            {
                // Add a more granular series for order execution.
                AddDataSeries(BarsPeriodType.Tick, 1);
            }
            else if (State == State.DataLoaded)
            {
                fastEma = EMA(10);
                slowEma = EMA(25);
            }
        }

        protected override void OnBarUpdate()
        {
            if (CurrentBars[0] < 25 || CurrentBars[1] < 1)
                return;

            // Evaluate entry conditions only on the primary series.
            if (BarsInProgress != 0)
                return;

            // Submit the order to BarsArray[1] for an intrabar fill.
            if (CrossAbove(fastEma, slowEma, 1))
                EnterLong(1, 1, "Long");

            else if (CrossBelow(fastEma, slowEma, 1))
                EnterShort(1, 1, "Short");
        }
    }
