    (5461, N'Enter on a Higher Timeframe and Exit on a Lower Timeframe', N'EntryAndExitDifferentTimeframes.cs', N'C#', N'Strategy', N'multi timeframe,higher timeframe,lower timeframe,entry exit,AddDataSeries,BarsInProgress,BarsArray', N'#region Using declarations
using NinjaTrader.Data;
using NinjaTrader.NinjaScript;
using NinjaTrader.NinjaScript.Indicators;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleMultiTimeFrameOrders : Strategy
    {
        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Multi Time Frame Orders";
                Calculate = Calculate.OnBarClose;
            }
            else if (State == State.Configure)
            {
                // BarsArray[1] = 5-minute series.
                AddDataSeries(BarsPeriodType.Minute, 5);

                // BarsArray[2] = 15-minute series.
                AddDataSeries(BarsPeriodType.Minute, 15);
            }
        }

        protected override void OnBarUpdate()
        {
            if (CurrentBars[1] < 10 || CurrentBars[2] < 50)
                return;

            // Monitor the faster 5-minute series for exits.
            if (BarsInProgress == 1)
            {
                if (SMA(BarsArray[1], 5)[0] <
                    SMA(BarsArray[1], 5)[1])
                {
                    ExitLong(
                        1,
                        1,
                        "5 Min Exit",
                        "15 Min Entry");
                }
            }

            // Monitor the slower 15-minute series for entries.
            else if (BarsInProgress == 2)
            {
                if (SMA(BarsArray[2], 25)[0] >
                    SMA(BarsArray[2], 50)[0])
                {
                    EnterLong(
                        2,
                        1,
                        "15 Min Entry");
                }
            }
        }
    }
