    (5462, N'Use an ATM Template and Track Trade P&L', N'TrackAtmStrategyPnL.cs', N'C#', N'Strategy', N'ATM strategy,ATM template,profit loss,order status,AtmStrategyCreate,realized P&L,unrealized P&L', N'#region Using declarations
using NinjaTrader.Cbi;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleATMPnL : Strategy
    {
        private string atmStrategyId = string.Empty;
        private string orderId = string.Empty;

        private bool atmCreated;
        private double realizedPnL;
        private double unrealizedPnL;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample ATM PnL";
                Calculate = Calculate.OnBarClose;
            }
        }

        protected override void OnBarUpdate()
        {
            // ATM strategies are real-time only.
            if (State != State.Realtime)
                return;

            // Create a new ATM trade when no ATM is currently active.
            if (atmStrategyId.Length == 0 &&
                orderId.Length == 0 &&
                Close[0] > Open[0])
            {
                atmStrategyId = GetAtmStrategyUniqueId();
                orderId = GetAtmStrategyUniqueId();

                AtmStrategyCreate(
                    OrderAction.Buy,
                    OrderType.Market,
                    0,
                    0,
                    TimeInForce.Day,
                    orderId,
                    "AtmStrategyTemplate",
                    atmStrategyId,
                    (errorCode, callbackId) =>
                    {
                        if (callbackId == atmStrategyId &&
                            errorCode == ErrorCode.NoError)
                        {
                            atmCreated = true;
                        }
                    });
            }

            // Monitor the ATM entry order.
            if (orderId.Length > 0)
            {
                string[] status =
                    GetAtmStrategyEntryOrderStatus(orderId);

                if (status.Length > 0 &&
                    (status[2] == "Filled" ||
                     status[2] == "Cancelled" ||
                     status[2] == "Rejected"))
                {
                    orderId = string.Empty;
                }
            }

            if (!atmCreated || atmStrategyId.Length == 0)
                return;

            // Track unrealized P&L while the ATM position is active.
            unrealizedPnL =
                GetAtmStrategyUnrealizedProfitLoss(
                    atmStrategyId);

            // When the ATM position closes, collect realized P&L.
            if (GetAtmStrategyMarketPosition(atmStrategyId)
                == MarketPosition.Flat)
            {
                realizedPnL =
                    GetAtmStrategyRealizedProfitLoss(
                        atmStrategyId);

                Print("ATM Realized P&L: " + realizedPnL);

                atmStrategyId = string.Empty;
                atmCreated = false;
                unrealizedPnL = 0;
            }
        }
    }
