    INSERT INTO #NinjaTraderRagUpdate
    (Id, Title, FilePath, Language, Category, Tags, Content, Embedding, Description, RagLevel)
    VALUES
    (5463, N'Stop a Strategy After Profit or Loss Limit', N'StopStrategyAtPnLLimit.cs', N'C#', N'Strategy', N'daily loss limit,profit target,stop strategy,max loss,cancel orders,close position,SystemPerformance', N'#region Using declarations
using System;
using NinjaTrader.Cbi;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleHaltBasicStrategy : Strategy
    {
        private Order entryOrder;
        private bool strategyHalted;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Halt Basic Strategy";
                Calculate = Calculate.OnBarClose;
                BarsRequiredToTrade = 20;
            }
        }

        protected override void OnBarUpdate()
        {
            if (CurrentBar < BarsRequiredToTrade)
                return;

            if (strategyHalted)
                return;

            double cumulativePnL =
                SystemPerformance.AllTrades
                    .TradesPerformance.Currency.CumProfit;

            // Stop trading after reaching either limit.
            if (cumulativePnL >= 1000 ||
                cumulativePnL <= -400)
            {
                HaltStrategy();
                strategyHalted = true;
                return;
            }

            // Normal strategy logic.
            if (Position.MarketPosition == MarketPosition.Flat &&
                Close[0] > Open[0])
            {
                EnterLongLimit(
                    0,
                    true,
                    1,
                    Low[0],
                    "Long Limit");
            }
        }

        protected override void OnOrderUpdate(
            Order order,
            double limitPrice,
            double stopPrice,
            int quantity,
            int filled,
            double averageFillPrice,
            OrderState orderState,
            DateTime time,
            ErrorCode error,
            string nativeError)
        {
            if (order.Name == "Long Limit")
                entryOrder = order;
        }

        private void HaltStrategy()
        {
            // Cancel any working entry order.
            if (entryOrder != null &&
                (entryOrder.OrderState == OrderState.Working ||
                 entryOrder.OrderState == OrderState.Accepted))
            {
                CancelOrder(entryOrder);
            }

            // Flatten any open position.
            if (Position.MarketPosition == MarketPosition.Long)
                ExitLong();

            else if (Position.MarketPosition == MarketPosition.Short)
                ExitShort();
        }
    }
