    (5464, N'Keep a Limit Order Active Until Explicitly Cancelled', N'PersistentLimitOrder.cs', N'C#', N'Strategy', N'persistent order,limit order,liveUntilCancelled,working order,EnterLongLimit,cancel order,pending order', N'#region Using declarations
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleIsLiveUntilCanceled : Strategy
    {
        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Live Until Cancelled";
                Calculate = Calculate.OnBarClose;
            }
        }

        protected override void OnBarUpdate()
        {
            double entryPrice = Low[0] - (2 * TickSize);

            // This order remains working until it fills
            // or is explicitly cancelled.
            if (CrossAbove(SMA(10), SMA(25), 1))
            {
                EnterLongLimit(
                    0,
                    true,
                    DefaultQuantity,
                    entryPrice,
                    "Persistent Long");
            }

            // With liveUntilCancelled = false, the order
            // is cancelled when the submission condition
            // is no longer true on a subsequent bar.
            if (Close[0] > Open[0])
            {
                EnterLongLimit(
                    0,
                    false,
                    DefaultQuantity,
                    entryPrice,
                    "Temporary Long");
            }
        }
    }
