    (5465, N'Move Stop Loss to Breakeven After Profit', N'MoveStopToBreakeven.cs', N'C#', N'Strategy', N'breakeven stop,stop loss,profit target,SetStopLoss,SetProfitTarget,AveragePrice,trade management', N'#region Using declarations
using NinjaTrader.Cbi;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SamplePriceModification : Strategy
    {
        private int stopLossTicks = 20;
        private int profitTargetTicks = 100;
        private int breakEvenTriggerTicks = 50;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Price Modification";
                Calculate = Calculate.OnBarClose;
            }
            else if (State == State.Configure)
            {
                // Initial protective orders are based on entry fill price.
                SetStopLoss(
                    CalculationMode.Ticks,
                    stopLossTicks);

                SetProfitTarget(
                    CalculationMode.Ticks,
                    profitTargetTicks);
            }
        }

        protected override void OnBarUpdate()
        {
            // Reset the stop for the next trade.
            if (Position.MarketPosition == MarketPosition.Flat)
            {
                SetStopLoss(
                    CalculationMode.Ticks,
                    stopLossTicks);
            }

            // Move the stop to breakeven after sufficient profit.
            else if (Position.MarketPosition == MarketPosition.Long)
            {
                if (Close[0] >=
                    Position.AveragePrice
                    + (breakEvenTriggerTicks * TickSize))
                {
                    SetStopLoss(
                        CalculationMode.Price,
                        Position.AveragePrice);
                }
            }

            // Example entry condition.
            if (Position.MarketPosition == MarketPosition.Flat &&
                Close[0] > Close[1])
            {
                EnterLong();
            }
        }
    }
