    (5466, N'Trade a Breakout Above the Initial Session High', N'InitialSessionHighBreakout.cs', N'C#', N'Strategy', N'breakout strategy,session high,initial range,bar high,EnterLongStopMarket,new session,BarsSinceNewTradingDay', N'#region Using declarations
using System.ComponentModel.DataAnnotations;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleBreakoutStrategy : Strategy
    {
        private double highestHigh;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Breakout Strategy";
                Calculate = Calculate.OnBarClose;

                RangeBars = 30;
            }
        }

        protected override void OnBarUpdate()
        {
            // Reset the breakout level at the start of each session.
            if (Bars.IsFirstBarOfSession)
                highestHigh = High[0];

            // Store the highest high during the initial range.
            if (Bars.BarsSinceNewTradingDay < RangeBars &&
                High[0] > highestHigh)
            {
                highestHigh = High[0];
            }

            // After the initial range is complete,
            // place a buy stop above the stored high.
            if (Bars.BarsSinceNewTradingDay >= RangeBars &&
                Position.MarketPosition == MarketPosition.Flat)
            {
                EnterLongStopMarket(
                    highestHigh + TickSize);
            }
        }

        [NinjaScriptProperty]
        [Range(1, int.MaxValue)]
        [Display(
            Name = "Range Bars",
            GroupName = "Parameters",
            Order = 0)]
        public int RangeBars
        {
            get;
            set;
        }
    }
