    (5467, N'Monitor Stop Loss and Profit Target Orders', N'MonitorStopAndTargetOrders.cs', N'C#', N'Strategy', N'monitor stop loss,profit target,OnOrderUpdate,Order object,order state,SetStopLoss,SetProfitTarget', N'#region Using declarations
using System;
using System.Collections.Generic;
using NinjaTrader.Cbi;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleMonitorStopProfit : Strategy
    {
        private List<Order> stopLossOrders;
        private List<Order> profitTargetOrders;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Monitor Stop Profit";
                Calculate = Calculate.OnBarClose;
            }
            else if (State == State.Configure)
            {
                stopLossOrders = new List<Order>();
                profitTargetOrders = new List<Order>();

                SetStopLoss(
                    CalculationMode.Ticks,
                    5);

                SetProfitTarget(
                    CalculationMode.Ticks,
                    10);
            }
        }

        protected override void OnBarUpdate()
        {
            if (State != State.Realtime)
                return;

            if (Position.MarketPosition == MarketPosition.Flat &&
                Close[0] > Open[0])
            {
                EnterLong();
            }
        }

        protected override void OnOrderUpdate(
            Order order,
            double limitPrice,
            double stopPrice,
            int quantity,
            int filled,
            double averageFillPrice,
            OrderState orderState,
            DateTime time,
            ErrorCode error,
            string nativeError)
        {
            // Capture protective orders when they are submitted.
            if (orderState == OrderState.Submitted)
            {
                if (order.Name == "Stop loss" &&
                    !stopLossOrders.Contains(order))
                {
                    stopLossOrders.Add(order);
                }

                else if (order.Name == "Profit target" &&
                         !profitTargetOrders.Contains(order))
                {
                    profitTargetOrders.Add(order);
                }
            }

            // Monitor stop-loss orders.
            if (stopLossOrders.Contains(order))
            {
                Print(
                    "Stop order state: "
                    + orderState
                    + " Price: "
                    + stopPrice);

                if (orderState == OrderState.Filled ||
                    orderState == OrderState.Cancelled ||
                    orderState == OrderState.Rejected)
                {
                    stopLossOrders.Remove(order);
                }
            }

            // Monitor profit-target orders.
            if (profitTargetOrders.Contains(order))
            {
                Print(
                    "Target order state: "
                    + orderState
                    + " Price: "
                    + limitPrice);

                if (orderState == OrderState.Filled ||
                    orderState == OrderState.Cancelled ||
                    orderState == OrderState.Rejected)
                {
                    profitTargetOrders.Remove(order);
                }
            }
        }
    }
