    INSERT INTO #NinjaTraderRagUpdate
    (Id, Title, FilePath, Language, Category, Tags, Content, Embedding, Description, RagLevel)
    VALUES
    (5468, N'Plot Strategy Values on Multiple Chart Panels', N'PlotValuesOnMultiplePanels.cs', N'C#', N'Strategy', N'strategy plot,plot strategy values,multiple panels,Series<double>,AddChartIndicator,chart panel,overlay plot', N'#region Using declarations
using System.ComponentModel;
using System.Xml.Serialization;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleStrategyPlot : Strategy
    {
        private SampleOverlayPlot overlayIndicator;
        private SamplePanelPlot panelIndicator;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Strategy Plot";
                Calculate = Calculate.OnBarClose;
            }
            else if (State == State.Configure)
            {
                // Store strategy values that will be plotted.
                OverlayPlot = new Series<double>(this);
                PanelPlot = new Series<double>(this);

                // Helper indicator for the price panel.
                overlayIndicator = SampleOverlayPlot();
                overlayIndicator.Strategy = this;
                AddChartIndicator(overlayIndicator);

                // Helper indicator for a separate panel.
                panelIndicator = SamplePanelPlot();
                panelIndicator.Strategy = this;
                AddChartIndicator(panelIndicator);
            }
        }

        protected override void OnBarUpdate()
        {
            // Internal strategy calculations to display.
            OverlayPlot[0] = Close[0];
            PanelPlot[0] = Low[0];

            // Force helper indicators to update historically.
            double overlayValue = overlayIndicator[0];
            double panelValue = panelIndicator[0];
        }

        [Browsable(false)]
        [XmlIgnore]
        public Series<double> OverlayPlot;

        [Browsable(false)]
        [XmlIgnore]
        public Series<double> PanelPlot;
    }
