    (5469, N'Draw Trade Levels and Remove Them When the Trade Closes', N'TradeLevelLines.cs', N'C#', N'Strategy', N'entry line,stop line,target line,RemoveDrawObject,Draw.Line,trade levels,chart cleanup', N'#region Using declarations
using System;
using System.Windows.Media;
using NinjaTrader.Cbi;
using NinjaTrader.Gui;
using NinjaTrader.NinjaScript;
using NinjaTrader.NinjaScript.DrawingTools;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleRemoveDrawObjects : Strategy
    {
        private int entryBar;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Remove Draw Objects";
                Calculate = Calculate.OnBarClose;
            }
        }

        protected override void OnBarUpdate()
        {
            if (State != State.Realtime)
                return;

            // Example entry.
            if (Position.MarketPosition == MarketPosition.Flat &&
                Close[0] > Open[0])
            {
                EnterLong("Entry");
                entryBar = CurrentBar;
            }

            if (Position.MarketPosition == MarketPosition.Long)
            {
                int lineLength =
                    Math.Max(CurrentBar - entryBar, 3);

                double entryPrice = Position.AveragePrice;
                double stopPrice = entryPrice - (10 * TickSize);
                double targetPrice = entryPrice + (10 * TickSize);

                Draw.Line(
                    this,
                    "EntryLine",
                    false,
                    lineLength,
                    entryPrice,
                    0,
                    entryPrice,
                    Brushes.Brown,
                    DashStyleHelper.Solid,
                    2);

                Draw.Line(
                    this,
                    "StopLine",
                    false,
                    lineLength,
                    stopPrice,
                    0,
                    stopPrice,
                    Brushes.Red,
                    DashStyleHelper.Solid,
                    2);

                Draw.Line(
                    this,
                    "TargetLine",
                    false,
                    lineLength,
                    targetPrice,
                    0,
                    targetPrice,
                    Brushes.Green,
                    DashStyleHelper.Solid,
                    2);
            }
            else if (Position.MarketPosition == MarketPosition.Flat)
            {
                RemoveDrawObject("EntryLine");
                RemoveDrawObject("StopLine");
                RemoveDrawObject("TargetLine");
            }
        }
    }
