    (5470, N'Reset a Trade Counter at the Start of Each Session', N'TradeLimitPerSession.cs', N'C#', N'Strategy', N'trade limit,reset each session,max trades,trade counter,IsFirstBarOfSession,session reset', N'#region Using declarations
using System.ComponentModel.DataAnnotations;
using NinjaTrader.Cbi;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleTradeLimiter : Strategy
    {
        private int tradeCounter;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Trade Limiter";
                Calculate = Calculate.OnBarClose;

                MaxTrades = 5;
            }
        }

        protected override void OnBarUpdate()
        {
            // Reset values at the beginning of each trading session.
            if (Bars.IsFirstBarOfSession && IsFirstTickOfBar)
                tradeCounter = 0;

            // Stop taking new trades after reaching the session limit.
            if (tradeCounter >= MaxTrades)
                return;

            if (Position.MarketPosition != MarketPosition.Flat)
                return;

            // Example entry condition.
            if (Close[0] > Open[0])
            {
                EnterLong();
                tradeCounter++;
            }
            else if (Close[0] < Open[0])
            {
                EnterShort();
                tradeCounter++;
            }
        }

        [NinjaScriptProperty]
        [Range(1, int.MaxValue)]
        [Display(
            Name = "Max Trades",
            GroupName = "Parameters",
            Order = 0)]
        public int MaxTrades
        {
            get;
            set;
        }
    }
