    (5471, N'Round a Price to the Instrument Tick Size', N'RoundPriceToTickSize.cs', N'C#', N'Strategy', N'round price,tick size,RoundToTickSize,limit price,stop price,order price', N'#region Using declarations
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleRoundToTickSize : Strategy
    {
        protected override void OnBarUpdate()
        {
            // Example calculated price that may not fall
            // exactly on the instrument''s tick increment.
            double calculatedPrice = SMA(10)[0];

            double roundedPrice =
                Instrument.MasterInstrument.RoundToTickSize(
                    calculatedPrice);

            Print("Calculated price: " + calculatedPrice);
            Print("Rounded price: " + roundedPrice);

            if (Position.MarketPosition == MarketPosition.Flat)
            {
                EnterLongLimit(
                    roundedPrice,
                    "Long");
            }
        }
    }
