    (5472, N'Scale Out with Partial Profit Target and Trailing Stop', N'ScaleOutPosition.cs', N'C#', N'Strategy', N'scale out,partial profit,take half profit,trailing stop,SetProfitTarget,SetTrailStop,named entries', N'#region Using declarations
using NinjaTrader.Cbi;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleScaleOut : Strategy
    {
        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Scale Out";
                Calculate = Calculate.OnBarClose;

                EntriesPerDirection = 1;
                EntryHandling = EntryHandling.UniqueEntries;
            }
            else if (State == State.Configure)
            {
                // Take profit on the first portion only.
                SetProfitTarget(
                    "Entry 1",
                    CalculationMode.Ticks,
                    10);

                // Protect the remaining position with a trailing stop.
                SetTrailStop(
                    CalculationMode.Ticks,
                    8);
            }
        }

        protected override void OnBarUpdate()
        {
            if (Position.MarketPosition != MarketPosition.Flat)
                return;

            // Example entry condition.
            if (Close[0] > Open[0])
            {
                // Separate entry signals allow each portion
                // of the position to be managed independently.
                EnterLong(1, "Entry 1");
                EnterLong(1, "Entry 2");
            }
        }
    }
