    INSERT INTO #NinjaTraderRagUpdate
    (Id, Title, FilePath, Language, Category, Tags, Content, Embedding, Description, RagLevel)
    VALUES
    (5473, N'Enter Once Per Bar and Exit on Every Tick', N'EnterOnceExitEveryTick.cs', N'C#', N'Strategy', N'once per bar,every tick,intrabar exit,IsFirstTickOfBar,OnEachTick,entry timing,exit timing', N'#region Using declarations
using NinjaTrader.Cbi;
using NinjaTrader.NinjaScript;
using NinjaTrader.NinjaScript.Indicators;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleEnterOnceExitEveryTick : Strategy
    {
        private SMA fast;
        private SMA slow;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Enter Once Exit Every Tick";
                Calculate = Calculate.OnEachTick;
            }
            else if (State == State.DataLoaded)
            {
                fast = SMA(10);
                slow = SMA(20);
            }
        }

        protected override void OnBarUpdate()
        {
            if (State == State.Historical)
                return;

            // Entry logic runs only once when a new bar begins.
            // Use [1] values to reference the bar that just closed.
            if (IsFirstTickOfBar &&
                Position.MarketPosition == MarketPosition.Flat)
            {
                if (fast[1] > slow[1] &&
                    fast[2] <= slow[2])
                {
                    EnterLong("Long Entry");
                }
            }

            // Exit logic runs on every incoming tick.
            if (Position.MarketPosition == MarketPosition.Long)
            {
                if (CrossBelow(fast, slow, 1))
                {
                    ExitLong(
                        "Intrabar Exit",
                        "Long Entry");
                }
            }
        }
    }
