    (5474, N'Stop Trading After Consecutive Losing Trades', N'StopAfterConsecutiveLosses.cs', N'C#', N'Strategy', N'consecutive losses,stop trading,losing trades,trade history,SystemPerformance,Trade object,session reset', N'#region Using declarations
using System.ComponentModel.DataAnnotations;
using NinjaTrader.Cbi;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleConsecutiveLosses : Strategy
    {
        private int sessionStartTradeCount;
        private int previousTradeCount;
        private bool tradingHalted;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Consecutive Losses";
                Calculate = Calculate.OnBarClose;

                ConsecutiveLossLimit = 3;
            }
        }

        protected override void OnBarUpdate()
        {
            // Start each trading session with a fresh loss count.
            if (Bars.IsFirstBarOfSession && IsFirstTickOfBar)
            {
                sessionStartTradeCount = SystemPerformance.AllTrades.Count;
                previousTradeCount = SystemPerformance.AllTrades.Count;
                tradingHalted = false;
            }

            int totalTrades = SystemPerformance.AllTrades.Count;
            int sessionTrades = totalTrades - sessionStartTradeCount;

            // Only check after a new trade has completed.
            if (totalTrades != previousTradeCount)
            {
                previousTradeCount = totalTrades;

                if (sessionTrades >= ConsecutiveLossLimit &&
                    LastTradesWereLosers(ConsecutiveLossLimit))
                {
                    tradingHalted = true;
                }
            }

            // No more entries for the remainder of this session.
            if (tradingHalted)
                return;

            // Example entry logic.
            if (Position.MarketPosition == MarketPosition.Flat &&
                Close[0] > Open[0])
            {
                EnterLong();
            }
        }

        private bool LastTradesWereLosers(int count)
        {
            if (SystemPerformance.AllTrades.Count < count)
                return false;

            for (int i = 1; i <= count; i++)
            {
                Trade trade =
                    SystemPerformance.AllTrades[
                        SystemPerformance.AllTrades.Count - i];

                if (trade.ProfitCurrency >= 0)
                    return false;
            }

            return true;
        }

        [NinjaScriptProperty]
        [Range(1, int.MaxValue)]
        [Display(
            Name = "Consecutive Loss Limit",
            GroupName = "Parameters",
            Order = 0)]
        public int ConsecutiveLossLimit
        {
            get;
            set;
        }
    }
