    (5475, N'Trade Breakouts Above or Below the Initial Session Range', N'InitialSessionRangeBreakout.cs', N'C#', N'Strategy', N'range breakout,session high,session low,CrossAbove,CrossBelow,OnEachTick,trailing stop', N'#region Using declarations
using System;
using System.ComponentModel.DataAnnotations;
using NinjaTrader.Cbi;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleHighLowCross : Strategy
    {
        private double highestHigh;
        private double lowestLow;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample High Low Cross";
                Calculate = Calculate.OnEachTick;

                RangeBars = 15;
                TrailStopTicks = 10;
            }
            else if (State == State.Configure)
            {
                SetTrailStop(
                    CalculationMode.Ticks,
                    TrailStopTicks);
            }
        }

        protected override void OnBarUpdate()
        {
            // Reset the range at the beginning of each session.
            if (Bars.IsFirstBarOfSession)
            {
                highestHigh = High[0];
                lowestLow = Low[0];
            }

            // Build the initial session range.
            if (Bars.BarsSinceNewTradingDay < RangeBars)
            {
                if (High[0] > highestHigh)
                    highestHigh = High[0];

                if (Low[0] < lowestLow)
                    lowestLow = Low[0];

                return;
            }

            if (Position.MarketPosition != MarketPosition.Flat)
                return;

            // Enter as soon as price crosses the stored range.
            if (CrossAbove(Close, highestHigh, 1))
                EnterLong("Range Breakout Long");

            else if (CrossBelow(Close, lowestLow, 1))
                EnterShort("Range Breakout Short");
        }

        [NinjaScriptProperty]
        [Range(1, int.MaxValue)]
        [Display(
            Name = "Range Bars",
            GroupName = "Parameters",
            Order = 0)]
        public int RangeBars
        {
            get;
            set;
        }

        [NinjaScriptProperty]
        [Range(1, int.MaxValue)]
        [Display(
            Name = "Trail Stop Ticks",
            GroupName = "Parameters",
            Order = 1)]
        public int TrailStopTicks
        {
            get;
            set;
        }
    }
