    (5476, N'Limit Strategy Trading to Specific Days and Times', N'TradingDayAndTimeFilter.cs', N'C#', N'Strategy', N'time filter,trading hours,day filter,ToTime,DayOfWeek,session filter,entry time', N'#region Using declarations
using System;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleTimeFilter : Strategy
    {
        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Time Filter";
                Calculate = Calculate.OnBarClose;
            }
        }

        protected override void OnBarUpdate()
        {
            // Example: exclude selected days.
            if (Time[0].DayOfWeek == DayOfWeek.Monday ||
                Time[0].DayOfWeek == DayOfWeek.Friday)
            {
                return;
            }

            int currentTime = ToTime(Time[0]);

            // Allow entries during either trading window.
            bool tradingTime =
                (currentTime >= 93000 &&
                 currentTime < 120000)
                ||
                (currentTime >= 140000 &&
                 currentTime < 154500);

            if (!tradingTime)
                return;

            // Example entry logic.
            if (Position.MarketPosition == MarketPosition.Flat &&
                Close[0] > Close[1])
            {
                EnterLong();
            }
        }
    }
