    (5477, N'Cancel a Working Order After a Number of Bars', N'CancelWorkingOrder.cs', N'C#', N'Strategy', N'cancel order,CancelOrder,pending order,working order,limit order,liveUntilCancelled,OnOrderUpdate', N'#region Using declarations
using System;
using NinjaTrader.Cbi;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleCancelOrder : Strategy
    {
        private Order entryOrder;
        private int entryBar;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Cancel Order";
                Calculate = Calculate.OnBarClose;

                CancelAfterBars = 3;
            }
            else if (State == State.Realtime)
            {
                // Convert a historical order reference to its
                // corresponding real-time order if necessary.
                if (entryOrder != null)
                    entryOrder = GetRealtimeOrder(entryOrder);
            }
        }

        protected override void OnBarUpdate()
        {
            if (Position.MarketPosition != MarketPosition.Flat)
                return;

            // Submit a limit order that stays active until cancelled.
            if (entryOrder == null && Close[0] > Close[1])
            {
                EnterLongLimit(
                    0,
                    true,
                    1,
                    Low[0] - (5 * TickSize),
                    "Long Limit");

                entryBar = CurrentBar;
            }

            // Cancel the order if it has remained unfilled too long.
            if (entryOrder != null &&
                CurrentBar >= entryBar + CancelAfterBars)
            {
                CancelOrder(entryOrder);
            }
        }

        protected override void OnOrderUpdate(
            Order order,
            double limitPrice,
            double stopPrice,
            int quantity,
            int filled,
            double averageFillPrice,
            OrderState orderState,
            DateTime time,
            ErrorCode error,
            string nativeError)
        {
            if (order.Name != "Long Limit")
                return;

            // Capture the Order object so it can be cancelled later.
            entryOrder = order;

            // Clear the reference when the order is no longer active.
            if (orderState == OrderState.Filled ||
                orderState == OrderState.Cancelled ||
                orderState == OrderState.Rejected)
            {
                entryOrder = null;
            }
        }

        [NinjaScriptProperty]
        public int CancelAfterBars
        {
            get;
            set;
        }
    }
