    INSERT INTO #NinjaTraderRagUpdate
    (Id, Title, FilePath, Language, Category, Tags, Content, Embedding, Description, RagLevel)
    VALUES
    (5478, N'Use Multiple Entry and Exit Signals in One Strategy', N'MultipleEntryExitSignals.cs', N'C#', N'Strategy', N'multiple entries,entry signals,exit signals,signal names,EntryHandling,EnterLong,ExitLong', N'#region Using declarations
using NinjaTrader.NinjaScript;
using NinjaTrader.NinjaScript.Indicators;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleMultipleEntryExitSignals : Strategy
    {
        private RSI rsi;
        private SMA sma;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Multiple Entry Exit Signals";
                Calculate = Calculate.OnBarClose;

                EntriesPerDirection = 1;
                EntryHandling = EntryHandling.AllEntries;
            }
            else if (State == State.DataLoaded)
            {
                rsi = RSI(14, 3);
                sma = SMA(5);

                AddChartIndicator(rsi);
                AddChartIndicator(sma);
            }
        }

        protected override void OnBarUpdate()
        {
            // Trading setup #1.
            if (CrossAbove(rsi, 20, 1))
                EnterLong("RSI Entry");

            if (CrossBelow(rsi, 80, 1))
                ExitLong("RSI Entry");

            // Trading setup #2.
            if (CrossAbove(sma, Close, 1))
                EnterLong("SMA Entry");

            if (CrossBelow(sma, Close, 1))
                ExitLong("SMA Entry");
        }
    }
