    (5479, N'Submit Stop and Target Orders After an Entry Fills', N'ProtectiveOrdersOnExecution.cs', N'C#', N'Strategy', N'OnExecutionUpdate,OnOrderUpdate,protective orders,stop loss,profit target,partial fills,breakeven', N'#region Using declarations
using System;
using NinjaTrader.Cbi;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleProtectiveOrders : Strategy
    {
        private Order entryOrder;
        private Order stopOrder;
        private Order targetOrder;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Protective Orders";
                Calculate = Calculate.OnBarClose;
            }
            else if (State == State.Realtime)
            {
                if (entryOrder != null)
                    entryOrder = GetRealtimeOrder(entryOrder);

                if (stopOrder != null)
                    stopOrder = GetRealtimeOrder(stopOrder);

                if (targetOrder != null)
                    targetOrder = GetRealtimeOrder(targetOrder);
            }
        }

        protected override void OnBarUpdate()
        {
            if (entryOrder == null &&
                Position.MarketPosition == MarketPosition.Flat)
            {
                EnterLong(1, "Entry");
            }

            // Move the manually managed stop to breakeven.
            if (Position.MarketPosition == MarketPosition.Long &&
                stopOrder != null &&
                Close[0] >= Position.AveragePrice + (4 * TickSize) &&
                stopOrder.StopPrice < Position.AveragePrice)
            {
                stopOrder = ExitLongStopMarket(
                    0,
                    true,
                    stopOrder.Quantity,
                    Position.AveragePrice,
                    "Stop",
                    "Entry");
            }
        }

        protected override void OnOrderUpdate(
            Order order,
            double limitPrice,
            double stopPrice,
            int quantity,
            int filled,
            double averageFillPrice,
            OrderState orderState,
            DateTime time,
            ErrorCode error,
            string nativeError)
        {
            // Capture the entry Order object.
            if (order.Name == "Entry")
            {
                entryOrder = order;

                if (orderState == OrderState.Cancelled &&
                    order.Filled == 0)
                {
                    entryOrder = null;
                }
            }
        }

        protected override void OnExecutionUpdate(
            Execution execution,
            string executionId,
            double price,
            int quantity,
            MarketPosition marketPosition,
            string orderId,
            DateTime time)
        {
            if (entryOrder == null ||
                execution.Order != entryOrder)
            {
                return;
            }

            if (execution.Order.OrderState == OrderState.PartFilled ||
                execution.Order.OrderState == OrderState.Filled)
            {
                int filledQuantity = execution.Order.Filled;
                double fillPrice = execution.Order.AverageFillPrice;

                // Submit or update protective orders immediately
                // after the entry execution.
                stopOrder = ExitLongStopMarket(
                    0,
                    true,
                    filledQuantity,
                    fillPrice - (4 * TickSize),
                    "Stop",
                    "Entry");

                targetOrder = ExitLongLimit(
                    0,
                    true,
                    filledQuantity,
                    fillPrice + (8 * TickSize),
                    "Target",
                    "Entry");
            }

            if (execution.Order.OrderState == OrderState.Filled)
                entryOrder = null;
        }
    }
