    (5480, N'Check Whether an Indicator or Price Series Is Rising or Falling', N'Strategies/Conditions/IsRisingIsFalling.cs', N'C#', N'Strategy', N'IsRising,IsFalling,trend direction,indicator rising,indicator falling,Series<T>,trend filter', N'#region Using declarations
using NinjaTrader.NinjaScript;
using NinjaTrader.NinjaScript.Indicators;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleIsFallingIsRising : Strategy
    {
        private ADX adx;
        private SMA sma;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Is Rising Is Falling";
                Calculate = Calculate.OnBarClose;
            }
            else if (State == State.DataLoaded)
            {
                adx = ADX(14);
                sma = SMA(14);
            }
        }

        protected override void OnBarUpdate()
        {
            if (CurrentBar < 1)
                return;

            // Enter when ADX is rising and SMA is falling.
            if (IsRising(adx) &&
                IsFalling(sma))
            {
                EnterLong();
            }

            // Exit when ADX begins falling.
            if (IsFalling(adx))
            {
                ExitLong();
            }
        }
    }
