    (5481, N'Stop Trading After Session Profit, Loss or Trade Limits', N'SessionPnLAndTradeLimits.cs', N'C#', N'Strategy', N'daily profit limit,daily loss limit,max trades,session P&L,SystemPerformance,CumProfit,risk management', N'#region Using declarations
using System.ComponentModel.DataAnnotations;
using NinjaTrader.NinjaScript;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SampleSessionLimits : Strategy
    {
        private int sessionStartTrades;
        private double sessionStartProfit;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Sample Session Limits";
                Calculate = Calculate.OnBarClose;

                ProfitLimit = 1000;
                LossLimit = 400;
                MaxTrades = 10;
            }
        }

        protected override void OnBarUpdate()
        {
            // Store cumulative values at the start of each session.
            if (Bars.IsFirstBarOfSession)
            {
                sessionStartTrades =
                    SystemPerformance.AllTrades.Count;

                sessionStartProfit =
                    SystemPerformance.AllTrades
                        .TradesPerformance.Currency.CumProfit;
            }

            double sessionProfit =
                SystemPerformance.AllTrades
                    .TradesPerformance.Currency.CumProfit
                - sessionStartProfit;

            int sessionTrades =
                SystemPerformance.AllTrades.Count
                - sessionStartTrades;

            // Prevent any further entries when a limit is reached.
            if (sessionProfit >= ProfitLimit ||
                sessionProfit <= -LossLimit ||
                sessionTrades >= MaxTrades)
            {
                return;
            }

            // Example entry logic.
            if (Position.MarketPosition == MarketPosition.Flat &&
                Close[0] > Close[1])
            {
                EnterLong();
            }
        }

        [NinjaScriptProperty]
        [Range(0, double.MaxValue)]
        public double ProfitLimit { get; set; }

        [NinjaScriptProperty]
        [Range(0, double.MaxValue)]
        public double LossLimit { get; set; }

        [NinjaScriptProperty]
        [Range(1, int.MaxValue)]
        public int MaxTrades { get; set; }
    }
